@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

/* DARK FUTURISTIC THEME - Navy to Teal Gradient with Cyan/Purple Accents */
:root {
  --button-outline: rgba(255,255,255, .10);
  --badge-outline: rgba(0, 217, 255, .20);

  --opaque-button-border-intensity: 12;

  --elevate-1: rgba(255,255,255, .05);
  --elevate-2: rgba(255,255,255, .10);

  /* Deep navy to teal gradient background */
  --background: 230 40% 12%;
  --background-gradient-start: #1a1530;
  --background-gradient-mid: #0f1f3d;
  --background-gradient-end: #1a3a52;

  /* Light gray text for readability on dark */
  --foreground: 215 20% 70%;

  /* Subtle dark borders */
  --border: 220 30% 20%;

  /* Glassmorphism cards */
  --card: 240 30% 15%;
  --card-foreground: 215 20% 85%;
  --card-border: 220 35% 25%;

  /* Sidebar */
  --sidebar: 230 35% 10%;
  --sidebar-foreground: 215 20% 80%;
  --sidebar-border: 220 30% 18%;
  --sidebar-primary: 190 100% 50%;
  --sidebar-primary-foreground: 0 0% 100%;
  --sidebar-accent: 220 35% 22%;
  --sidebar-accent-foreground: 215 20% 85%;
  --sidebar-ring: 190 100% 50%;

  /* Popover */
  --popover: 235 35% 14%;
  --popover-foreground: 215 20% 85%;
  --popover-border: 220 35% 22%;

  /* Primary: Bright Cyan */
  --primary: 190 100% 50%;
  --primary-foreground: 220 40% 8%;

  /* Secondary: Semi-transparent for glass effect */
  --secondary: 230 30% 20%;
  --secondary-foreground: 215 20% 85%;

  /* Muted: Darker tones */
  --muted: 225 25% 18%;
  --muted-foreground: 220 15% 55%;

  /* Accent: Purple/Magenta */
  --accent: 280 80% 65%;
  --accent-foreground: 0 0% 100%;

  /* Destructive */
  --destructive: 0 75% 55%;
  --destructive-foreground: 0 0% 100%;

  /* Input */
  --input: 220 30% 22%;
  --ring: 190 100% 50%;

  /* Charts - Cyan, Purple, Magenta spectrum */
  --chart-1: 190 100% 50%;
  --chart-2: 280 80% 65%;
  --chart-3: 320 80% 60%;
  --chart-4: 250 80% 65%;
  --chart-5: 210 90% 60%;

  /* Typography */
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-serif: Georgia, serif;
  --font-mono: 'JetBrains Mono', 'Menlo', 'Monaco', 'Courier New', monospace;

  /* Radius */
  --radius: .625rem;

  /* Shadows with cyan glow */
  --shadow-2xs: 0px 1px 1px 0px rgba(0, 0, 0, 0.3);
  --shadow-xs: 0px 1px 2px 0px rgba(0, 0, 0, 0.4);
  --shadow-sm: 0px 1px 3px 0px rgba(0, 0, 0, 0.4), 0px 1px 2px -1px rgba(0, 0, 0, 0.3);
  --shadow: 0px 2px 4px -1px rgba(0, 0, 0, 0.4), 0px 4px 6px -1px rgba(0, 0, 0, 0.3);
  --shadow-md: 0px 4px 6px -1px rgba(0, 0, 0, 0.4), 0px 2px 4px -2px rgba(0, 0, 0, 0.3);
  --shadow-lg: 0px 10px 15px -3px rgba(0, 0, 0, 0.4), 0px 4px 6px -4px rgba(0, 0, 0, 0.3);
  --shadow-xl: 0px 20px 25px -5px rgba(0, 0, 0, 0.4), 0px 8px 10px -6px rgba(0, 0, 0, 0.3);
  --shadow-2xl: 0px 25px 50px -12px rgba(0, 0, 0, 0.5);

  /* Glow effects */
  --glow-cyan: 0 0 20px rgba(0, 217, 255, 0.4), 0 0 40px rgba(0, 217, 255, 0.2);
  --glow-cyan-sm: 0 0 10px rgba(0, 217, 255, 0.3);
  --glow-cyan-lg: 0 0 30px rgba(0, 217, 255, 0.5), 0 0 60px rgba(0, 217, 255, 0.25);
  --glow-purple: 0 0 20px rgba(168, 85, 247, 0.4), 0 0 40px rgba(168, 85, 247, 0.2);
  --glow-purple-sm: 0 0 10px rgba(168, 85, 247, 0.3);

  --tracking-normal: 0em;
  --spacing: 0.25rem;

  /* Border computations */
  --sidebar-primary-border: hsl(var(--sidebar-primary));
  --sidebar-primary-border: hsl(from hsl(var(--sidebar-primary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --sidebar-accent-border: hsl(var(--sidebar-accent));
  --sidebar-accent-border: hsl(from hsl(var(--sidebar-accent)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --primary-border: hsl(var(--primary));
  --primary-border: hsl(from hsl(var(--primary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --secondary-border: hsl(var(--secondary));
  --secondary-border: hsl(from hsl(var(--secondary)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --muted-border: hsl(var(--muted));
  --muted-border: hsl(from hsl(var(--muted)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --accent-border: hsl(var(--accent));
  --accent-border: hsl(from hsl(var(--accent)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
  --destructive-border: hsl(var(--destructive));
  --destructive-border: hsl(from hsl(var(--destructive)) h s calc(l + var(--opaque-button-border-intensity)) / alpha);
}

/* Dark mode is now the default - keep .dark for compatibility */
.dark {
  --button-outline: rgba(255,255,255, .10);
  --badge-outline: rgba(0, 217, 255, .20);
  --opaque-button-border-intensity: 12;
  --elevate-1: rgba(255,255,255, .05);
  --elevate-2: rgba(255,255,255, .10);
  --background: 230 40% 12%;
  --foreground: 215 20% 70%;
  --border: 220 30% 20%;
  --card: 240 30% 15%;
  --card-foreground: 215 20% 85%;
  --card-border: 220 35% 25%;
  --sidebar: 230 35% 10%;
  --sidebar-foreground: 215 20% 80%;
  --sidebar-border: 220 30% 18%;
  --sidebar-primary: 190 100% 50%;
  --sidebar-primary-foreground: 0 0% 100%;
  --sidebar-accent: 220 35% 22%;
  --sidebar-accent-foreground: 215 20% 85%;
  --sidebar-ring: 190 100% 50%;
  --popover: 235 35% 14%;
  --popover-foreground: 215 20% 85%;
  --popover-border: 220 35% 22%;
  --primary: 190 100% 50%;
  --primary-foreground: 220 40% 8%;
  --secondary: 230 30% 20%;
  --secondary-foreground: 215 20% 85%;
  --muted: 225 25% 18%;
  --muted-foreground: 220 15% 55%;
  --accent: 280 80% 65%;
  --accent-foreground: 0 0% 100%;
  --destructive: 0 75% 55%;
  --destructive-foreground: 0 0% 100%;
  --input: 220 30% 22%;
  --ring: 190 100% 50%;
  --chart-1: 190 100% 50%;
  --chart-2: 280 80% 65%;
  --chart-3: 320 80% 60%;
  --chart-4: 250 80% 65%;
  --chart-5: 210 90% 60%;
}

@layer base {
  * {
    @apply border-border;
  }

  html {
    color-scheme: dark;
  }

  body {
    @apply font-sans antialiased text-foreground;
    background: linear-gradient(135deg, var(--background-gradient-start) 0%, var(--background-gradient-mid) 50%, var(--background-gradient-end) 100%);
    background-attachment: fixed;
    min-height: 100vh;
  }
}

@layer utilities {
  /* Hide ugly search cancel button in Chrome */
  input[type="search"]::-webkit-search-cancel-button {
    @apply hidden;
  }

  /* Placeholder styling for contentEditable div */
  [contenteditable][data-placeholder]:empty::before {
    content: attr(data-placeholder);
    color: hsl(var(--muted-foreground));
    pointer-events: none;
  }

  .no-default-hover-elevate {}
  .no-default-active-elevate {}

  /* Toggle elevation system */
  .toggle-elevate::before,
  .toggle-elevate-2::before {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: -1;
  }

  .toggle-elevate.toggle-elevated::before {
    background-color: var(--elevate-2);
  }

  .border.toggle-elevate::before {
    inset: -1px;
  }

  /* Hover/Active elevation */
  .hover-elevate:not(.no-default-hover-elevate),
  .active-elevate:not(.no-default-active-elevate),
  .hover-elevate-2:not(.no-default-hover-elevate),
  .active-elevate-2:not(.no-default-active-elevate) {
    position: relative;
    z-index: 0;
  }

  .hover-elevate:not(.no-default-hover-elevate)::after,
  .active-elevate:not(.no-default-active-elevate)::after,
  .hover-elevate-2:not(.no-default-hover-elevate)::after,
  .active-elevate-2:not(.no-default-active-elevate)::after {
    content: "";
    pointer-events: none;
    position: absolute;
    inset: 0px;
    border-radius: inherit;
    z-index: 999;
  }

  .hover-elevate:hover:not(.no-default-hover-elevate)::after,
  .active-elevate:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-1);
  }

  .hover-elevate-2:hover:not(.no-default-hover-elevate)::after,
  .active-elevate-2:active:not(.no-default-active-elevate)::after {
    background-color: var(--elevate-2);
  }

  .border.hover-elevate:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate:not(.no-active-interaction-elevate)::after,
  .border.hover-elevate-2:not(.no-hover-interaction-elevate)::after,
  .border.active-elevate-2:not(.no-active-interaction-elevate)::after {
    inset: -1px;
  }

  /* Glassmorphism effect */
  .glass {
    background: rgba(30, 30, 63, 0.4);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(45, 58, 94, 0.5);
  }

  .glass-card {
    background: rgba(30, 30, 63, 0.5);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(45, 58, 94, 0.6);
  }

  .glass-hover:hover {
    border-color: rgba(0, 217, 255, 0.5);
    box-shadow: var(--glow-cyan-sm);
  }

  /* Glow effects */
  .glow-cyan {
    box-shadow: var(--glow-cyan);
  }

  .glow-cyan-sm {
    box-shadow: var(--glow-cyan-sm);
  }

  .glow-cyan-lg {
    box-shadow: var(--glow-cyan-lg);
  }

  .glow-purple {
    box-shadow: var(--glow-purple);
  }

  .glow-purple-sm {
    box-shadow: var(--glow-purple-sm);
  }

  /* Icon glow */
  .icon-glow {
    filter: drop-shadow(0 0 8px rgba(0, 217, 255, 0.6));
  }

  .icon-glow-purple {
    filter: drop-shadow(0 0 8px rgba(168, 85, 247, 0.6));
  }

  /* Text gradients */
  .text-gradient-cyan {
    background: linear-gradient(135deg, #00d9ff 0%, #00b4d8 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .text-gradient-purple {
    background: linear-gradient(135deg, #a855f7 0%, #d946ef 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .text-gradient-cyan-purple {
    background: linear-gradient(135deg, #00d9ff 0%, #a855f7 50%, #d946ef 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  /* Purple gradient button */
  .btn-gradient-purple {
    background: linear-gradient(135deg, #a855f7 0%, #d946ef 100%);
    color: white;
    border: none;
    transition: all 0.2s ease;
  }

  .btn-gradient-purple:hover {
    box-shadow: 0 0 20px rgba(168, 85, 247, 0.5), 0 0 40px rgba(217, 70, 239, 0.3);
    transform: translateY(-1px);
  }

  /* Cyan border button */
  .btn-outline-cyan {
    background: transparent;
    border: 1px solid #00d9ff;
    color: #00d9ff;
    transition: all 0.2s ease;
  }

  .btn-outline-cyan:hover {
    background: rgba(0, 217, 255, 0.1);
    box-shadow: var(--glow-cyan-sm);
  }

  /* Badge glow */
  .badge-glow {
    border: 1px solid rgba(0, 217, 255, 0.6);
    background: rgba(0, 217, 255, 0.1);
    backdrop-filter: blur(4px);
    box-shadow: 0 0 15px rgba(0, 217, 255, 0.25);
  }

  /* Pulse animation for hero glow */
  .pulse-glow {
    animation: pulseGlow 3s ease-in-out infinite;
  }

  @keyframes pulseGlow {
    0%, 100% {
      box-shadow: 0 0 40px rgba(0, 217, 255, 0.4), 0 0 80px rgba(0, 217, 255, 0.2);
    }
    50% {
      box-shadow: 0 0 60px rgba(0, 217, 255, 0.5), 0 0 120px rgba(0, 217, 255, 0.3);
    }
  }

  /* Fade in animation */
  .fade-in {
    animation: fadeIn 0.5s ease-out;
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Score ring glow */
  .score-ring {
    filter: drop-shadow(0 0 15px rgba(0, 217, 255, 0.5));
  }

  /* Card hover glow effect */
  .card-glow-hover {
    transition: all 0.3s ease;
  }

  .card-glow-hover:hover {
    border-color: rgba(0, 217, 255, 0.4);
    box-shadow: 0 0 25px rgba(0, 217, 255, 0.15), 0 4px 20px rgba(0, 0, 0, 0.3);
  }

  /* Metric score highlight */
  .metric-score {
    text-shadow: 0 0 20px rgba(0, 217, 255, 0.5);
  }

  /* Navigation bar style */
  .nav-dark {
    background: rgba(15, 15, 30, 0.9);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid rgba(45, 58, 94, 0.5);
  }

  /* Search input futuristic style */
  .search-futuristic {
    background: rgba(30, 30, 63, 0.6);
    border: 1px solid rgba(45, 58, 94, 0.6);
    border-radius: 24px;
    backdrop-filter: blur(8px);
    transition: all 0.3s ease;
  }

  .search-futuristic:focus-within {
    border-color: rgba(0, 217, 255, 0.5);
    box-shadow: 0 0 20px rgba(0, 217, 255, 0.2);
  }

  /* Hero radial glow background */
  .hero-glow {
    position: relative;
  }

  .hero-glow::before {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 600px;
    height: 600px;
    background: radial-gradient(circle, rgba(0, 217, 255, 0.15) 0%, rgba(0, 217, 255, 0.05) 40%, transparent 70%);
    pointer-events: none;
    z-index: 0;
  }

  /* Status indicator badges */
  .status-badge-success {
    background: rgba(34, 197, 94, 0.15);
    border: 1px solid rgba(34, 197, 94, 0.4);
    color: #22c55e;
  }

  .status-badge-warning {
    background: rgba(245, 158, 11, 0.15);
    border: 1px solid rgba(245, 158, 11, 0.4);
    color: #f59e0b;
  }

  .status-badge-error {
    background: rgba(239, 68, 68, 0.15);
    border: 1px solid rgba(239, 68, 68, 0.4);
    color: #ef4444;
  }
}

