import type { CensusData, GrowthData, WalkabilityData, SchoolData, ScoreBreakdown, PropertyListingsData, MarketData, CrimeData } from "@shared/schema";

export interface ForecastData {
  homeValueForecast?: {
    oneYearForecast: number;
    currentValue: number | null;
    forecastDate: string;
  } | null;
  rentForecast?: {
    oneYearForecast: number;
    currentRent: number | null;
    forecastDate: string;
  } | null;
  marketVelocity?: {
    daysToClose: number | null;
    daysToPending: number | null;
    saleToListRatio: number | null;
  } | null;
}

interface ScoreCalculationInput {
  demographics: CensusData & GrowthData;
  walkability: WalkabilityData;
  propertyListings?: PropertyListingsData | null;
  marketData?: MarketData | null;
  schools?: SchoolData | null;
  crimeData?: CrimeData | null;
  forecasts?: ForecastData | null;
}

export function calculateInvestmentScore(data: ScoreCalculationInput): {
  finalScore: number;
  scoreBreakdown: ScoreBreakdown[];
} {
  // Calculate individual component scores (0-100)
  const demographicScore = calculateDemographicScore(data.demographics);
  const walkabilityScore = (data.walkability.walkScore / 100) * 100;

  // Calculate school quality score from real data
  // Uses SchoolDigger Pro metrics for comprehensive scoring
  let schoolQuality = 50; // Default if no school data available
  if (data.schools) {
    let baseScore = 50;
    let bonusPoints = 0;

    // Primary: Use state percentile (most accurate measure)
    if (data.schools.average_state_percentile && data.schools.average_state_percentile > 0) {
      baseScore = data.schools.average_state_percentile;
    } else if (data.schools.average_star_rating && data.schools.average_star_rating > 0) {
      // Convert 5-star rating to 100-point scale
      baseScore = (data.schools.average_star_rating / 5) * 100;
    } else {
      // Fall back to calculated average_score (1-10 scale)
      baseScore = (data.schools.average_score / 10) * 100;
    }

    // Pro tier: Graduation rate bonus (up to +8 points)
    if (data.schools.average_graduation_rate && data.schools.average_graduation_rate > 0) {
      if (data.schools.average_graduation_rate >= 95) bonusPoints += 8;
      else if (data.schools.average_graduation_rate >= 90) bonusPoints += 6;
      else if (data.schools.average_graduation_rate >= 85) bonusPoints += 4;
      else if (data.schools.average_graduation_rate >= 80) bonusPoints += 2;
      else if (data.schools.average_graduation_rate < 70) bonusPoints -= 5;
    }

    // Pro tier: Chronic absenteeism penalty (up to -10 points)
    if (data.schools.average_absenteeism_rate !== undefined && data.schools.average_absenteeism_rate > 0) {
      if (data.schools.average_absenteeism_rate > 25) bonusPoints -= 10;
      else if (data.schools.average_absenteeism_rate > 20) bonusPoints -= 6;
      else if (data.schools.average_absenteeism_rate > 15) bonusPoints -= 3;
      else if (data.schools.average_absenteeism_rate < 10) bonusPoints += 3;
    }

    // Pro tier: Spending per pupil bonus (up to +5 points)
    // Higher spending often correlates with better resources
    if (data.schools.average_spending_per_pupil && data.schools.average_spending_per_pupil > 0) {
      if (data.schools.average_spending_per_pupil >= 15000) bonusPoints += 5;
      else if (data.schools.average_spending_per_pupil >= 12000) bonusPoints += 3;
      else if (data.schools.average_spending_per_pupil >= 10000) bonusPoints += 1;
      else if (data.schools.average_spending_per_pupil < 8000) bonusPoints -= 2;
    }

    schoolQuality = Math.min(100, Math.max(0, baseScore + bonusPoints));
  }

  // Calculate market strength from real data + forecasts
  const marketStrength = calculateMarketStrength(data.propertyListings, data.marketData, data.demographics, data.forecasts);

  // Calculate safety score - prefer FBI crime data, fall back to Census proxy data
  const safetyScore = data.crimeData 
    ? data.crimeData.safetyScore  // Use real FBI crime data
    : calculateSafetyScore(data.demographics);  // Fall back to Census proxy

  // Calculate rental potential from real rent and home value data + forecasts
  const rentalPotential = calculateRentalPotential(data.demographics, data.propertyListings, data.marketData, data.forecasts);

  const scoreBreakdown: ScoreBreakdown[] = [
    { label: 'Market Strength', score: marketStrength, weight: 0.25 },
    { label: 'Demographic Trends', score: demographicScore, weight: 0.20 },
    { label: 'School Quality', score: schoolQuality, weight: 0.20 },
    { label: 'Safety Score', score: safetyScore, weight: 0.15 },
    { label: 'Walkability', score: walkabilityScore, weight: 0.10 },
    { label: 'Rental Potential', score: rentalPotential, weight: 0.10 },
  ];

  // Calculate weighted final score (1-10 scale)
  const finalScore = scoreBreakdown.reduce((total, item) => {
    return total + (item.score * item.weight);
  }, 0) / 10;

  return {
    finalScore: parseFloat(finalScore.toFixed(1)),
    scoreBreakdown
  };
}

function calculateDemographicScore(demographics: CensusData & GrowthData): number {
  let score = 50; // Base score

  // Income factor (up to +20 points)
  if (demographics.medianIncome > 100000) score += 20;
  else if (demographics.medianIncome > 75000) score += 15;
  else if (demographics.medianIncome > 50000) score += 10;
  else if (demographics.medianIncome > 35000) score += 5;

  // Employment factor (up to +8 points) - slightly reduced to make room for professional employment
  if (demographics.employmentRate > 95) score += 8;
  else if (demographics.employmentRate > 90) score += 6;
  else if (demographics.employmentRate > 85) score += 3;

  // Education factor (up to +10 points)
  if (demographics.collegeDegreePct > 50) score += 10;
  else if (demographics.collegeDegreePct > 35) score += 7;
  else if (demographics.collegeDegreePct > 25) score += 4;

  // Professional Employment factor (up to +7 points) - NEW
  // High concentration of professional workers indicates affluent, stable area
  if (demographics.professionalEmploymentPct > 60) score += 7;       // Very high (executive/tech hubs)
  else if (demographics.professionalEmploymentPct > 50) score += 6;  // High
  else if (demographics.professionalEmploymentPct > 40) score += 5;  // Above average
  else if (demographics.professionalEmploymentPct > 30) score += 3;  // Average
  else if (demographics.professionalEmploymentPct > 20) score += 1;  // Below average

  // Growth factors (up to +10 points)
  const avgGrowth = (demographics.populationGrowth5yr + demographics.incomeGrowth5yr + demographics.housingGrowth5yr) / 3;
  if (avgGrowth > 10) score += 10;
  else if (avgGrowth > 5) score += 7;
  else if (avgGrowth > 2) score += 4;
  else if (avgGrowth < -5) score -= 10;

  return Math.min(100, Math.max(0, score));
}

function calculateMarketStrength(
  propertyListings: PropertyListingsData | null | undefined,
  marketData: MarketData | null | undefined,
  demographics: CensusData & GrowthData,
  forecasts?: ForecastData | null
): number {
  let totalScore = 0;
  let maxPossibleScore = 0;

  // Days on Market factor (30 points max) - reduced from 40 to make room for new factors
  if (propertyListings?.avg_days_on_market !== null && propertyListings?.avg_days_on_market !== undefined) {
    const dom = propertyListings.avg_days_on_market;
    let domScore = 0;

    if (dom < 15) domScore = 30;
    else if (dom < 30) domScore = 26;
    else if (dom < 45) domScore = 21;
    else if (dom < 60) domScore = 15;
    else if (dom < 90) domScore = 9;
    else if (dom < 120) domScore = 4;
    else domScore = 0;

    totalScore += domScore;
    maxPossibleScore += 30;
  }

  // Homeownership rate factor (25 points max) - reduced from 30
  if (marketData?.homeownershipRate !== null && marketData?.homeownershipRate !== undefined) {
    const rate = marketData.homeownershipRate;
    let ownershipScore = 0;

    if (rate > 75) ownershipScore = 25;
    else if (rate > 70) ownershipScore = 23;
    else if (rate > 65) ownershipScore = 20;
    else if (rate > 60) ownershipScore = 17;
    else if (rate > 55) ownershipScore = 13;
    else if (rate > 50) ownershipScore = 10;
    else if (rate > 45) ownershipScore = 7;
    else if (rate > 40) ownershipScore = 3;
    else ownershipScore = 0;

    totalScore += ownershipScore;
    maxPossibleScore += 25;
  }

  // Vacancy rate factor (25 points max) - reduced from 30
  if (marketData?.vacancyRate !== null && marketData?.vacancyRate !== undefined) {
    const vacancy = marketData.vacancyRate;
    let vacancyScore = 0;

    if (vacancy < 3) vacancyScore = 25;
    else if (vacancy < 5) vacancyScore = 23;
    else if (vacancy < 7) vacancyScore = 20;
    else if (vacancy < 10) vacancyScore = 17;
    else if (vacancy < 12) vacancyScore = 13;
    else if (vacancy < 15) vacancyScore = 8;
    else if (vacancy < 18) vacancyScore = 4;
    else vacancyScore = 0;

    totalScore += vacancyScore;
    maxPossibleScore += 25;
  }

  // Property Age factor (10 points max) - NEW
  // Newer properties generally indicate growth and investment
  if (demographics.medianYearBuilt > 0) {
    const currentYear = new Date().getFullYear();
    const propertyAge = currentYear - demographics.medianYearBuilt;
    let ageScore = 0;

    if (propertyAge < 10) ageScore = 10;        // Very new (2015+)
    else if (propertyAge < 20) ageScore = 9;    // New (2005-2014)
    else if (propertyAge < 30) ageScore = 7;    // Relatively new (1995-2004)
    else if (propertyAge < 40) ageScore = 5;    // Moderate age (1985-1994)
    else if (propertyAge < 50) ageScore = 3;    // Older (1975-1984)
    else ageScore = 2;                          // Very old (pre-1975)

    totalScore += ageScore;
    maxPossibleScore += 10;
  }

  // High-Value Home Concentration factor (10 points max) - NEW
  // Higher concentration of expensive homes indicates premium market
  // Normalized per 1,000 housing units to scale fairly across ZIP sizes
  if (demographics.highValueHomePer1000 > 0) {
    let highValueScore = 0;
    const per1000 = demographics.highValueHomePer1000;

    if (per1000 >= 500) highValueScore = 10;      // 50%+ homes are high-value (ultra-premium)
    else if (per1000 >= 300) highValueScore = 9;  // 30%+ (very premium)
    else if (per1000 >= 200) highValueScore = 8;  // 20%+ (premium)
    else if (per1000 >= 100) highValueScore = 6;  // 10%+ (upper-middle)
    else if (per1000 >= 50) highValueScore = 4;   // 5%+ (above average)
    else highValueScore = 2;                      // <5% (has some luxury homes)

    totalScore += highValueScore;
    maxPossibleScore += 10;
  }

  // Home Value Forecast factor (15 points max) - NEW from Zillow data
  // Positive forecast = market appreciation expected
  if (forecasts?.homeValueForecast?.oneYearForecast !== undefined && forecasts.homeValueForecast.oneYearForecast !== null) {
    const forecast = forecasts.homeValueForecast.oneYearForecast;
    let forecastScore = 0;

    if (forecast >= 8) forecastScore = 15;       // 8%+ growth (hot market)
    else if (forecast >= 5) forecastScore = 13;  // 5-8% (strong growth)
    else if (forecast >= 3) forecastScore = 11;  // 3-5% (healthy growth)
    else if (forecast >= 1) forecastScore = 8;   // 1-3% (modest growth)
    else if (forecast >= 0) forecastScore = 5;   // 0-1% (stable)
    else if (forecast >= -2) forecastScore = 2;  // -2 to 0 (slight decline)
    else forecastScore = 0;                      // <-2% (declining market)

    totalScore += forecastScore;
    maxPossibleScore += 15;
  }

  // Market Velocity - Days to Pending (10 points max) - NEW from Zillow
  // Faster sales = stronger demand
  if (forecasts?.marketVelocity?.daysToPending !== undefined && forecasts.marketVelocity.daysToPending !== null) {
    const daysToPending = forecasts.marketVelocity.daysToPending;
    let velocityScore = 0;

    if (daysToPending < 10) velocityScore = 10;      // Very hot (< 10 days)
    else if (daysToPending < 15) velocityScore = 9;  // Hot market
    else if (daysToPending < 21) velocityScore = 7;  // Strong demand
    else if (daysToPending < 30) velocityScore = 5;  // Healthy market
    else if (daysToPending < 45) velocityScore = 3;  // Slower market
    else velocityScore = 1;                          // Slow market

    totalScore += velocityScore;
    maxPossibleScore += 10;
  }

  // Sale to List Ratio (10 points max) - NEW from Zillow
  // Higher ratio = sellers getting asking price or above
  if (forecasts?.marketVelocity?.saleToListRatio !== undefined && forecasts.marketVelocity.saleToListRatio !== null) {
    const ratio = forecasts.marketVelocity.saleToListRatio;
    let ratioScore = 0;

    if (ratio >= 1.02) ratioScore = 10;      // 102%+ (seller's market, bidding wars)
    else if (ratio >= 1.00) ratioScore = 9;  // 100-102% (full asking price)
    else if (ratio >= 0.98) ratioScore = 7;  // 98-100% (healthy market)
    else if (ratio >= 0.95) ratioScore = 5;  // 95-98% (slight buyer's market)
    else if (ratio >= 0.92) ratioScore = 3;  // 92-95% (buyer's market)
    else ratioScore = 1;                     // <92% (deep discounting)

    totalScore += ratioScore;
    maxPossibleScore += 10;
  }

  // If we have no data, return default score
  if (maxPossibleScore === 0) return 50;

  // Scale to 0-100 based on available components
  const finalScore = (totalScore / maxPossibleScore) * 100;

  return Math.min(100, Math.max(0, Math.round(finalScore)));
}

function calculateSafetyScore(demographics: CensusData & GrowthData): number {
  let score = 100; // Start with perfect score

  // Poverty rate penalty (up to -50 points)
  // Research shows strong correlation between poverty and crime
  const povertyRate = demographics.povertyRate;
  if (povertyRate > 30) score -= 50;        // Very high poverty
  else if (povertyRate > 20) score -= 40;   // High poverty
  else if (povertyRate > 15) score -= 30;   // Moderate-high poverty
  else if (povertyRate > 10) score -= 20;   // Moderate poverty
  else if (povertyRate > 5) score -= 10;    // Low poverty
  else score -= 0;                          // Very low poverty (good)

  // Abandonment rate penalty (up to -30 points)
  // High abandonment indicates neighborhood decline and potential crime
  const abandonmentRate = demographics.abandonmentRate;
  if (abandonmentRate > 40) score -= 30;    // Very high abandonment
  else if (abandonmentRate > 30) score -= 25; // High abandonment
  else if (abandonmentRate > 20) score -= 20; // Moderate-high
  else if (abandonmentRate > 10) score -= 12; // Moderate
  else if (abandonmentRate > 5) score -= 5;   // Low
  else score -= 0;                            // Very low (good)

  // Vacancy rate penalty (up to -20 points)
  // Different from market vacancy - high overall vacancy can indicate problems
  const vacancyRate = demographics.vacancyRate;
  if (vacancyRate > 20) score -= 20;        // Very high vacancy
  else if (vacancyRate > 15) score -= 15;   // High vacancy
  else if (vacancyRate > 12) score -= 10;   // Moderate-high
  else if (vacancyRate > 10) score -= 5;    // Moderate
  else score -= 0;                          // Low vacancy (good)

  return Math.min(100, Math.max(0, score));
}

function calculateRentalPotential(
  demographics: CensusData & GrowthData,
  propertyListings: PropertyListingsData | null | undefined,
  marketData: MarketData | null | undefined,
  forecasts?: ForecastData | null
): number {
  let score = 50; // Base score

  // Get median home value from Census or Market Data API
  const medianHomeValue = demographics.medianHomeValue > 0 
    ? demographics.medianHomeValue 
    : (marketData?.medianHomeValue || 0);

  // Get median rent from Census or Market Data API
  const medianRent = demographics.medianRent > 0 
    ? demographics.medianRent 
    : (marketData?.medianRent || 0);

  // Calculate rent-to-price ratio (annual yield)
  if (medianRent > 0 && medianHomeValue > 0) {
    const annualRent = medianRent * 12;
    const rentToPrice = (annualRent / medianHomeValue) * 100;

    // Rent-to-price ratio scoring (up to +30 points)
    // 1%+ is considered excellent for investors
    if (rentToPrice >= 1.0) score += 30;        // Excellent ROI (1%+ rule)
    else if (rentToPrice >= 0.8) score += 25;   // Very good ROI
    else if (rentToPrice >= 0.7) score += 20;   // Good ROI
    else if (rentToPrice >= 0.6) score += 15;   // Moderate ROI
    else if (rentToPrice >= 0.5) score += 10;   // Fair ROI
    else if (rentToPrice >= 0.4) score += 5;    // Low ROI
    else score += 0;                            // Poor ROI
  }

  // Owner vs Renter balance scoring (up to +20 points)
  // Moderate renter population (30-50%) is ideal for rental investments
  const renterPct = demographics.renterOccupiedPct;
  if (renterPct >= 30 && renterPct <= 50) score += 20;      // Ideal rental market
  else if (renterPct >= 25 && renterPct < 30) score += 15;  // Good rental market
  else if (renterPct >= 20 && renterPct < 25) score += 10;  // Moderate
  else if (renterPct > 50 && renterPct <= 60) score += 15;  // Also good (high rental demand)
  else if (renterPct > 60) score += 10;                     // Very high (may indicate affordability issues)
  else score += 5;                                          // Low rental market

  // Rent Forecast Bonus (up to +15 points) - NEW from Zillow data
  // Positive rent growth forecast improves rental potential
  if (forecasts?.rentForecast?.oneYearForecast !== undefined && forecasts.rentForecast.oneYearForecast !== null) {
    const rentGrowth = forecasts.rentForecast.oneYearForecast;

    if (rentGrowth >= 5) score += 15;       // 5%+ rent growth expected
    else if (rentGrowth >= 3) score += 12;  // 3-5% rent growth
    else if (rentGrowth >= 2) score += 9;   // 2-3% rent growth
    else if (rentGrowth >= 1) score += 6;   // 1-2% rent growth
    else if (rentGrowth >= 0) score += 3;   // 0-1% stable
    else score += 0;                        // Negative forecast
  }

  return Math.min(100, Math.max(0, score));
}

