                </div>
                <div>
                  <p className="text-xs text-gray-500">15-Year Fixed</p>
                  <p className="text-sm font-mono text-cyan-400">{rates.fifteenYearFixed}%</p>
                </div>
                <div>
                  <p className="text-xs text-gray-500">FHA</p>
