import { db } from '../../db';
import { fredMortgageRates, dataPipelineStatus } from '@shared/schema';
import { eq, desc, sql } from 'drizzle-orm';

const FRED_API_BASE = 'https://api.stlouisfed.org/fred';
const SERIES_ID = 'MORTGAGE30US';

interface FREDObservation {
  date: string;
  value: string;
}

interface FREDSeriesResponse {
  observations: FREDObservation[];
}

export async function downloadFredMortgageRates(): Promise<{ success: boolean; recordCount: number; message: string }> {
  const apiKey = process.env.FRED_API_KEY;

  if (!apiKey) {
    return { success: false, recordCount: 0, message: 'FRED_API_KEY not configured' };
  }

  try {
    console.log('[FRED Pipeline] Starting mortgage rate download...');

    const url = `${FRED_API_BASE}/series/observations?series_id=${SERIES_ID}&api_key=${apiKey}&file_type=json&sort_order=desc&limit=520`;

    const response = await fetch(url);

    if (!response.ok) {
      throw new Error(`FRED API returned ${response.status}`);
    }

    const data: FREDSeriesResponse = await response.json();
    const observations = data.observations || [];

    if (observations.length === 0) {
      return { success: false, recordCount: 0, message: 'No observations returned from FRED' };
    }

    const validRecords = observations
      .filter(obs => obs.value !== '.' && obs.value !== '' && obs.value !== 'ND')
      .map(obs => ({
        observationDate: obs.date,
        rate: parseFloat(obs.value),
        seriesId: SERIES_ID,
      }));

    await db.delete(fredMortgageRates).where(eq(fredMortgageRates.seriesId, SERIES_ID));

    if (validRecords.length > 0) {
      const batchSize = 100;
      for (let i = 0; i < validRecords.length; i += batchSize) {
        const batch = validRecords.slice(i, i + batchSize);
        await db.insert(fredMortgageRates).values(batch);
      }
    }

    await updatePipelineStatus('fred_mortgage_rates', validRecords.length, 'success');

    console.log(`[FRED Pipeline] Downloaded ${validRecords.length} mortgage rate observations`);
    return { success: true, recordCount: validRecords.length, message: `Downloaded ${validRecords.length} observations` };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    console.error('[FRED Pipeline] Error:', errorMessage);
    await updatePipelineStatus('fred_mortgage_rates', 0, 'error', errorMessage);
    return { success: false, recordCount: 0, message: errorMessage };
  }
}

export async function getMortgageRatesFromCache(limit: number = 60): Promise<{ date: string; rate: number }[]> {
  const records = await db
    .select({
      date: fredMortgageRates.observationDate,
      rate: fredMortgageRates.rate,
    })
    .from(fredMortgageRates)
    .orderBy(desc(fredMortgageRates.observationDate))
    .limit(limit);

  return records.map(r => ({
    date: r.date,
    rate: r.rate,
  }));
}

export async function getLatestMortgageRate(): Promise<{ date: string; rate: number } | null> {
  const records = await getMortgageRatesFromCache(1);
  return records.length > 0 ? records[0] : null;
}

async function updatePipelineStatus(
  dataSource: string,
  recordCount: number,
  status: 'success' | 'error' | 'pending',
  errorMessage?: string
): Promise<void> {
  const now = new Date();

  await db
    .insert(dataPipelineStatus)
    .values({
      dataSource,
      lastDownloadAt: now,
      lastSuccessAt: status === 'success' ? now : undefined,
      recordCount,
      status,
      errorMessage: errorMessage || null,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: dataPipelineStatus.dataSource,
      set: {
        lastDownloadAt: now,
        lastSuccessAt: status === 'success' ? now : sql`${dataPipelineStatus.lastSuccessAt}`,
        recordCount,
        status,
        errorMessage: errorMessage || null,
        updatedAt: now,
      },
    });
}

server/services/fredMortgage.ts.content:
import { getCachedMortgageRates } from './dataPipeline/dataCache';

export interface RateDataPoint {
  date: string;
  rate: number;
}

export interface MortgageTrendData {
  currentRate: number;
  previousWeekRate: number;
  previousMonthRate: number;
  previousYearRate: number;
  weekOverWeekChange: number;
  monthOverMonthChange: number;
  yearOverYearChange: number;
  trendDirection: 'rising' | 'falling' | 'stable';
  trendStrength: 'strong' | 'moderate' | 'slight';
  historicalAverage: number;
  vsHistoricalAverage: number;
  rateOutlook: string;
  lastUpdated: string;
  dataSource: string;
  historicalRates: RateDataPoint[];
}

const FRED_SERIES_ID = 'MORTGAGE30US';
const FRED_API_BASE = 'https://api.stlouisfed.org/fred';

interface FREDObservation {
  date: string;
  value: string;
}

interface FREDSeriesResponse {
  observations: FREDObservation[];
}

async function fetchFREDSeries(seriesId: string, limit: number = 100): Promise<FREDObservation[]> {
  const apiKey = process.env.FRED_API_KEY;

  if (!apiKey) {
    console.log('[FRED] No API key configured, using fallback data');
    return [];
  }

  const url = `${FRED_API_BASE}/series/observations?series_id=${seriesId}&api_key=${apiKey}&file_type=json&sort_order=desc&limit=${limit}`;

  try {
    const response = await fetch(url);

    if (!response.ok) {
      console.log(`[FRED] API returned ${response.status}`);
      return [];
    }

    const data: FREDSeriesResponse = await response.json();
    return data.observations || [];
  } catch (error) {
    console.error('[FRED] API error:', error);
    return [];
  }
}

function parseRate(value: string): number | null {
  if (value === '.' || value === '' || value === 'ND') {
    return null;
  }
  const parsed = parseFloat(value);
  return isNaN(parsed) ? null : parsed;
}

function calculateTrendDirection(current: number, previous: number): 'rising' | 'falling' | 'stable' {
  const change = current - previous;
  if (Math.abs(change) < 0.05) return 'stable';
  return change > 0 ? 'rising' : 'falling';
}

function calculateTrendStrength(yearChange: number): 'strong' | 'moderate' | 'slight' {
  const absChange = Math.abs(yearChange);
  if (absChange > 1.0) return 'strong';
  if (absChange > 0.5) return 'moderate';
  return 'slight';
}

function generateRateOutlook(trendDirection: string, trendStrength: string, vsHistorical: number): string {
  const historicalContext = vsHistorical > 0.5 
    ? 'above historical average' 
    : vsHistorical < -0.5 
      ? 'below historical average' 
      : 'near historical average';

  if (trendDirection === 'rising' && trendStrength === 'strong') {
    return `Rates are rising strongly and ${historicalContext}. Consider locking in soon if buying.`;
  } else if (trendDirection === 'rising') {
    return `Rates are trending upward and ${historicalContext}. Monitor closely for buying opportunities.`;
  } else if (trendDirection === 'falling' && trendStrength === 'strong') {
    return `Rates are falling significantly and ${historicalContext}. Good time to explore financing options.`;
  } else if (trendDirection === 'falling') {
    return `Rates are trending downward and ${historicalContext}. Favorable conditions for buyers.`;
  } else {
    return `Rates are stable and ${historicalContext}. Predictable environment for planning.`;
  }
}

async function getObservationsFromCacheOrAPI(): Promise<{ date: string; value: number }[]> {
  const cachedRates = await getCachedMortgageRates(60);

  const validCachedRates = cachedRates.filter(r => r.rate > 0 && !isNaN(r.rate));

  if (validCachedRates.length >= 10) {
    console.log(`[FRED] Using ${validCachedRates.length} cached mortgage rates`);
    return validCachedRates.map(r => ({ date: r.date, value: r.rate }));
  }

  console.log('[FRED] Cache insufficient, fetching from API');
  const observations = await fetchFREDSeries(FRED_SERIES_ID, 60);

  return observations
    .map(obs => ({ date: obs.date, value: parseRate(obs.value) }))
    .filter(obs => obs.value !== null) as { date: string; value: number }[];
}

export async function fetchMortgageTrends(): Promise<MortgageTrendData> {
  const validObservations = await getObservationsFromCacheOrAPI();

  if (validObservations.length < 2) {
    return getDefaultTrendData();
  }

  const currentRate = validObservations[0].value;
  const currentDate = validObservations[0].date;

  const oneWeekAgo = new Date();
  oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

  const oneMonthAgo = new Date();
  oneMonthAgo.setMonth(oneMonthAgo.getMonth() - 1);

  const oneYearAgo = new Date();
  oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

  const findClosestRate = (targetDate: Date): number => {
    const targetTime = targetDate.getTime();
    let closest = validObservations[0];
    let minDiff = Infinity;

    for (const obs of validObservations) {
      const obsTime = new Date(obs.date).getTime();
      const diff = Math.abs(obsTime - targetTime);
      if (diff < minDiff) {
        minDiff = diff;
        closest = obs;
      }
    }
    return closest.value;
  };

  const previousWeekRate = findClosestRate(oneWeekAgo);
  const previousMonthRate = findClosestRate(oneMonthAgo);
  const previousYearRate = findClosestRate(oneYearAgo);

  const sum = validObservations.reduce((acc, obs) => acc + obs.value, 0);
  const historicalAverage = sum / validObservations.length;

  const weekOverWeekChange = currentRate - previousWeekRate;
  const monthOverMonthChange = currentRate - previousMonthRate;
  const yearOverYearChange = currentRate - previousYearRate;
  const vsHistoricalAverage = currentRate - historicalAverage;

  const trendDirection = calculateTrendDirection(currentRate, previousMonthRate);
  const trendStrength = calculateTrendStrength(yearOverYearChange);
  const rateOutlook = generateRateOutlook(trendDirection, trendStrength, vsHistoricalAverage);

  const historicalRates: RateDataPoint[] = validObservations
    .slice(0, 52)
    .map(obs => ({ date: obs.date, rate: parseFloat(obs.value.toFixed(2)) }))
    .reverse();

  return {
    currentRate: parseFloat(currentRate.toFixed(2)),
    previousWeekRate: parseFloat(previousWeekRate.toFixed(2)),
    previousMonthRate: parseFloat(previousMonthRate.toFixed(2)),
    previousYearRate: parseFloat(previousYearRate.toFixed(2)),
    weekOverWeekChange: parseFloat(weekOverWeekChange.toFixed(2)),
    monthOverMonthChange: parseFloat(monthOverMonthChange.toFixed(2)),
    yearOverYearChange: parseFloat(yearOverYearChange.toFixed(2)),
    trendDirection,
    trendStrength,
    historicalAverage: parseFloat(historicalAverage.toFixed(2)),
    vsHistoricalAverage: parseFloat(vsHistoricalAverage.toFixed(2)),
    rateOutlook,
    lastUpdated: currentDate,
    dataSource: 'FRED (Federal Reserve Economic Data)',
    historicalRates
  };
}

function getDefaultTrendData(): MortgageTrendData {
  const defaultHistory: RateDataPoint[] = [];
  const today = new Date();
  for (let i = 51; i >= 0; i--) {
    const date = new Date(today);
    date.setDate(date.getDate() - i * 7);
    defaultHistory.push({
      date: date.toISOString().split('T')[0],
      rate: 6.5 + Math.sin(i / 10) * 0.3 + (i / 100)
    });
  }

  return {
    currentRate: 6.75,
    previousWeekRate: 6.80,
    previousMonthRate: 6.90,
    previousYearRate: 7.10,
    weekOverWeekChange: -0.05,
    monthOverMonthChange: -0.15,
    yearOverYearChange: -0.35,
    trendDirection: 'falling',
    trendStrength: 'slight',
    historicalAverage: 6.50,
    vsHistoricalAverage: 0.25,
    rateOutlook: 'Rates are trending downward and near historical average. Favorable conditions for buyers.',
    lastUpdated: new Date().toISOString().split('T')[0],
    dataSource: 'Default estimates (FRED API unavailable)',
    historicalRates: defaultHistory
  };
}

server/services/hudFairMarketRent.ts.content:
export interface FairMarketRent {
  zipCode: string;
  countyName: string;
  stateCode: string;
  fiscalYear: number;
  efficiency: number;
  oneBedroom: number;
  twoBedroom: number;
  threeBedroom: number;
  fourBedroom: number;
  smallAreaFMR: boolean;
  metroPrimaryEstimate: boolean;
  source: 'hud_api' | 'fallback_estimate';
}

export interface FMRComparison {
  fmr: FairMarketRent;
  marketRent: number;
  fmrVsMarket: number;
  section8Viable: boolean;
  section8Insight: string;
  rentalStrategyRecommendation: string;
}

const HUD_API_BASE = 'https://www.huduser.gov/hudapi/public/fmr';

async function fetchFromHUD(zipCode: string): Promise<FairMarketRent | null> {
  const hudToken = process.env.HUD_API_KEY || process.env.HUD_TOKEN;

  if (!hudToken) {
    console.log('[HUD] No API key configured');
    return null;
  }

  const currentYear = new Date().getFullYear();
  const fiscalYear = currentYear;

  try {
    const url = `${HUD_API_BASE}/data/${zipCode}?year=${fiscalYear}`;
    console.log(`[HUD] Fetching FMR for ZIP ${zipCode}, FY${fiscalYear}`);

    const response = await fetch(url, {
      headers: {
        'Authorization': `Bearer ${hudToken}`,
        'Content-Type': 'application/json'
      }
    });

    if (!response.ok) {
      console.log(`[HUD] API returned ${response.status}`);
      return null;
    }

    const data = await response.json();

    if (!data || !data.data || !data.data.basicdata) {
      console.log('[HUD] Unexpected response format');
      return null;
    }

    const basicData = data.data.basicdata;

    return {
      zipCode,
      countyName: basicData.county_name || 'Unknown County',
      stateCode: basicData.state_name || '',
      fiscalYear,
      efficiency: basicData.Efficiency || 0,
      oneBedroom: basicData.One_Bedroom || 0,
      twoBedroom: basicData.Two_Bedroom || 0,
      threeBedroom: basicData.Three_Bedroom || 0,
      fourBedroom: basicData.Four_Bedroom || 0,
      smallAreaFMR: basicData.smallarea_status === '1',
      metroPrimaryEstimate: basicData.metro === '1',
      source: 'hud_api'
    };
  } catch (error) {
    console.error('[HUD] API error:', error);
    return null;
  }
}

function estimateFMRFromCensus(
  zipCode: string,
  medianRent: number,
  stateCode: string
): FairMarketRent {
  const multiplier = 1.05;
  const baseFMR = Math.round(medianRent * multiplier);

  return {
    zipCode,
    countyName: 'Estimated',
    stateCode,
    fiscalYear: new Date().getFullYear(),
    efficiency: Math.round(baseFMR * 0.70),
    oneBedroom: Math.round(baseFMR * 0.85),
    twoBedroom: baseFMR,
    threeBedroom: Math.round(baseFMR * 1.25),
    fourBedroom: Math.round(baseFMR * 1.45),
    smallAreaFMR: false,
    metroPrimaryEstimate: false,
    source: 'fallback_estimate'
  };
}

export async function fetchFairMarketRent(
  zipCode: string,
  medianRentFallback: number,
  stateCode: string
): Promise<FairMarketRent> {
  const hudData = await fetchFromHUD(zipCode);

  if (hudData) {
    return hudData;
  }

  console.log(`[HUD] Using fallback FMR estimate for ZIP ${zipCode}`);
  return estimateFMRFromCensus(zipCode, medianRentFallback, stateCode);
}

export function analyzeFMRComparison(
  fmr: FairMarketRent,
  marketRent: number,
  bedroomCount: number = 2
): FMRComparison {
  let fmrForUnit: number;

  switch (bedroomCount) {
    case 0:
      fmrForUnit = fmr.efficiency;
      break;
    case 1:
      fmrForUnit = fmr.oneBedroom;
      break;
    case 2:
      fmrForUnit = fmr.twoBedroom;
      break;
    case 3:
      fmrForUnit = fmr.threeBedroom;
      break;
    case 4:
    default:
      fmrForUnit = fmr.fourBedroom;
      break;
  }

  const fmrVsMarket = marketRent > 0 
    ? ((fmrForUnit - marketRent) / marketRent) * 100 
    : 0;

  const section8Viable = fmrForUnit >= marketRent * 0.90;

  let section8Insight: string;
  let rentalStrategyRecommendation: string;

  if (fmrVsMarket >= 10) {
    section8Insight = `FMR is ${fmrVsMarket.toFixed(0)}% above market rent. Excellent Section 8 opportunity - voucher covers full market rent with room to spare.`;
    rentalStrategyRecommendation = 'Section 8 tenants are highly viable. Consider marketing to voucher holders for guaranteed rent.';
  } else if (fmrVsMarket >= 0) {
    section8Insight = `FMR roughly matches market rent. Section 8 vouchers will cover typical rents in this area.`;
    rentalStrategyRecommendation = 'Mixed strategy - both market-rate and Section 8 tenants are viable options.';
  } else if (fmrVsMarket >= -10) {
    section8Insight = `FMR is ${Math.abs(fmrVsMarket).toFixed(0)}% below market rent. Section 8 may cover most but not all market rents.`;
    rentalStrategyRecommendation = 'Section 8 viable for units priced at or slightly below market. Consider rent adjustment.';
  } else {
    section8Insight = `FMR is significantly below market rent (${Math.abs(fmrVsMarket).toFixed(0)}% gap). Section 8 vouchers likely insufficient.`;
    rentalStrategyRecommendation = 'Focus on market-rate tenants. Section 8 not economically viable without significant rent reduction.';
  }

  return {
    fmr,
    marketRent,
    fmrVsMarket: parseFloat(fmrVsMarket.toFixed(1)),
    section8Viable,
    section8Insight,
    rentalStrategyRecommendation
  };
}

server/services/unifiedCrime.ts.content:
/**
 * Unified Crime Data Service
 * 
 * Orchestrates data from three sources:
 * 1. Crime Data by ZipCode API (RapidAPI) - ZIP-level grades
 * 2. FBI Crime Data Explorer - State-level crime rates
 * 3. NIBRS API - National benchmarks
 * 
 * Calculates a composite safety score and provides rich crime analysis.
 */

import { fetchCrimeByZipCode, getGradeLabel, getGradeColor, type ZipCodeCrimeGrade, type NearbyZipCrime, type ZipCodeCrimeResult } from './crimeByZipcode';
import { fetchStateCrimeData, extractStateFromAddress, type CrimeData } from './fbiCrime';
import { fetchNationalCrimeBenchmarks, getCrimeTypeBreakdowns, compareToNational, type NationalCrimeBenchmark, type CrimeTypeBreakdown } from './nibrs';
import type { EnrichedCrimeData } from '@shared/schema';

export type { EnrichedCrimeData };

function getSafetyLabel(score: number): string {
  if (score >= 85) return 'Very Safe';
  if (score >= 70) return 'Safe';
  if (score >= 55) return 'Average';
  if (score >= 40) return 'Below Average';
  return 'Higher Risk';
}

function getSafetyColor(score: number): string {
  if (score >= 85) return '#22c55e';
  if (score >= 70) return '#84cc16';
  if (score >= 55) return '#eab308';
  if (score >= 40) return '#f97316';
  return '#ef4444';
}

function calculateCompositeScore(
  zipData: ZipCodeCrimeGrade | null,
  stateData: CrimeData | null,
  _nationalData: NationalCrimeBenchmark
): number {
  let totalScore = 0;
  let totalWeight = 0;

  if (zipData) {
    totalScore += zipData.overallScore * 0.60;
    totalWeight += 0.60;
  }

  if (stateData) {
    const stateScore = stateData.safetyScore;

    if (zipData) {
      totalScore += stateScore * 0.40;
      totalWeight += 0.40;
    } else {
      totalScore += stateScore * 0.70;
      totalWeight += 0.70;
    }
  }

  if (totalWeight === 0) {
    return 50;
  }

  return Math.round(totalScore / totalWeight);
}

function generateSummary(
  zipData: ZipCodeCrimeGrade | null,
  stateData: CrimeData | null,
  compositeScore: number
): { headline: string; description: string; keyInsights: string[] } {
  const insights: string[] = [];
  let headline = '';
  let description = '';

  if (zipData) {
    headline = `Safety Grade: ${zipData.overallGrade}`;

    if (zipData.overallScore >= 85) {
      description = 'This ZIP code is rated as very safe with significantly lower crime rates than average.';
    } else if (zipData.overallScore >= 70) {
      description = 'This ZIP code has a good safety rating with crime rates below average.';
    } else if (zipData.overallScore >= 55) {
      description = 'This ZIP code has average crime levels typical of most areas.';
    } else if (zipData.overallScore >= 40) {
      description = 'This ZIP code has crime rates somewhat higher than average.';
    } else {
      description = 'This ZIP code has elevated crime rates. Extra safety precautions may be advisable.';
    }

    if (zipData.violentCrimeScore >= 80) {
      insights.push('Low violent crime rate');
    } else if (zipData.violentCrimeScore < 50) {
      insights.push('Elevated violent crime concerns');
    }

    if (zipData.propertyCrimeScore >= 80) {
      insights.push('Low property crime rate');
    } else if (zipData.propertyCrimeScore < 50) {
      insights.push('Higher property crime rate');
    }
  } else if (stateData) {
    headline = `State Safety: ${stateData.stateName}`;

    if (stateData.violentCrimeVsNational < -20) {
      description = `${stateData.stateName} has significantly lower crime rates than the national average.`;
      insights.push('State crime rates well below national average');
    } else if (stateData.violentCrimeVsNational < 0) {
      description = `${stateData.stateName} has crime rates below the national average.`;
      insights.push('State crime rates below national average');
    } else if (stateData.violentCrimeVsNational < 20) {
      description = `${stateData.stateName} has crime rates near the national average.`;
      insights.push('State crime rates near national average');
    } else {
      description = `${stateData.stateName} has crime rates above the national average.`;
      insights.push('State crime rates above national average');
    }
  } else {
    headline = 'Limited Crime Data Available';
    description = 'Detailed crime statistics are not available for this area. The safety score is estimated based on available demographic indicators.';
    insights.push('Crime data sourced from demographic indicators');
  }

  if (stateData && zipData) {
    const comparison = compareToNational(stateData.violentCrimeRate, stateData.nationalViolentCrimeRate);
    if (comparison.comparison === 'much-lower' || comparison.comparison === 'lower') {
      insights.push(`State violent crime ${Math.abs(Math.round(comparison.percentDiff))}% below national avg`);
    } else if (comparison.comparison === 'higher' || comparison.comparison === 'much-higher') {
      insights.push(`State violent crime ${Math.round(comparison.percentDiff)}% above national avg`);
    }
  }

  return { headline, description, keyInsights: insights.slice(0, 4) };
}

export async function fetchEnrichedCrimeData(
  zipCode: string,
  address: string
): Promise<EnrichedCrimeData> {
  const stateAbbr = extractStateFromAddress(address);

  const [zipResult, stateData, nationalData] = await Promise.all([
    fetchCrimeByZipCode(zipCode),
    stateAbbr ? fetchStateCrimeData(stateAbbr) : Promise.resolve(null),
    fetchNationalCrimeBenchmarks()
  ]);

  const zipData = zipResult?.mainZip || null;
  const nearbyZips = zipResult?.nearbyZips || [];

  const compositeScore = calculateCompositeScore(zipData, stateData, nationalData);
  const summary = generateSummary(zipData, stateData, compositeScore);

  const enrichedData: EnrichedCrimeData = {
    zipCode,
    stateAbbr: stateAbbr || '',
    stateName: stateData?.stateName || '',

    zipLevelData: zipData ? {
      available: true,
      overallGrade: zipData.overallGrade,
      overallScore: zipData.overallScore,
      violentCrimeGrade: zipData.violentCrimeGrade,
      violentCrimeScore: zipData.violentCrimeScore,
      propertyCrimeGrade: zipData.propertyCrimeGrade,
      propertyCrimeScore: zipData.propertyCrimeScore,
      gradeLabel: getGradeLabel(zipData.overallGrade),
      gradeColor: getGradeColor(zipData.overallGrade),
      dataYear: zipData.dataYear
    } : null,

    nearbyZips: nearbyZips.map(nz => ({
      zipCode: nz.zipCode,
      state: nz.state,
      overallGrade: nz.overallGrade,
      violentCrimeGrade: nz.violentCrimeGrade,
      propertyCrimeGrade: nz.propertyCrimeGrade,
      overallScore: nz.overallScore,
      gradeColor: nz.gradeColor
    })),

    stateLevelData: stateData ? {
      available: true,
      violentCrimeRate: stateData.violentCrimeRate,
      propertyCrimeRate: stateData.propertyCrimeRate,
      violentCrimeVsNational: stateData.violentCrimeVsNational,
      propertyCrimeVsNational: stateData.propertyCrimeVsNational,
      violentCrimeComparison: compareToNational(stateData.violentCrimeRate, stateData.nationalViolentCrimeRate).label,
      propertyCrimeComparison: compareToNational(stateData.propertyCrimeRate, stateData.nationalPropertyCrimeRate).label,
      murderRate: stateData.murderRate,
      robberyRate: stateData.robberyRate,
      assaultRate: stateData.assaultRate,
      burglaryRate: stateData.burglaryRate,
      larcenyRate: stateData.larcenyRate,
      motorVehicleTheftRate: stateData.motorVehicleTheftRate,
      dataYear: stateData.year
    } : null,

    nationalBenchmarks: {
      available: true,
      violentVictimizationRate: nationalData.violentVictimizationRate,
      propertyVictimizationRate: nationalData.propertyVictimizationRate,
      crimeTypeBreakdowns: getCrimeTypeBreakdowns(),
      dataYear: nationalData.year
    },

    compositeSafetyScore: compositeScore,
    safetyLabel: getSafetyLabel(compositeScore),
    safetyColor: getSafetyColor(compositeScore),

    dataSources: {
      zipCode: zipData ? 'rapidapi' : 'unavailable',
      state: stateData ? (process.env.FBI_CRIME_API_KEY ? 'fbi' : 'cached') : 'unavailable',
      national: 'nibrs'
    },

    summary
  };

  console.log(`[UnifiedCrime] ${zipCode}: Composite score ${compositeScore} (${enrichedData.safetyLabel}), Sources: ZIP=${enrichedData.dataSources.zipCode}, State=${enrichedData.dataSources.state}`);

  return enrichedData;
}

export function convertToLegacyCrimeData(enrichedData: EnrichedCrimeData): CrimeData {
  const stateData = enrichedData.stateLevelData;

  return {
    stateAbbr: enrichedData.stateAbbr,
    stateName: enrichedData.stateName,
    year: stateData?.dataYear || new Date().getFullYear() - 1,
    population: 0,
    violentCrimeRate: stateData?.violentCrimeRate || 380.7,
    propertyCrimeRate: stateData?.propertyCrimeRate || 1954.4,
    violentCrimeTotal: 0,
    propertyCrimeTotal: 0,
    murderRate: stateData?.murderRate || 0,
    robberyRate: stateData?.robberyRate || 0,
    assaultRate: stateData?.assaultRate || 0,
    burglaryRate: stateData?.burglaryRate || 0,
    larcenyRate: stateData?.larcenyRate || 0,
    motorVehicleTheftRate: stateData?.motorVehicleTheftRate || 0,
    nationalViolentCrimeRate: 380.7,
    nationalPropertyCrimeRate: 1954.4,
    violentCrimeVsNational: stateData?.violentCrimeVsNational || 0,
    propertyCrimeVsNational: stateData?.propertyCrimeVsNational || 0,
    safetyScore: enrichedData.compositeSafetyScore
  };
}

