server/services/dataPipeline/hudDownload.content:
import { db } from '../../db';
import { hudFairMarketRent, dataPipelineStatus } from '@shared/schema';
import { eq, and, sql } from 'drizzle-orm';

const HUD_API_BASE = 'https://www.huduser.gov/hudapi/public/fmr';

const STATE_CODES = [
  'AL', 'AK', 'AZ', 'AR', 'CA', 'CO', 'CT', 'DE', 'DC', 'FL',
  'GA', 'HI', 'ID', 'IL', 'IN', 'IA', 'KS', 'KY', 'LA', 'ME',
  'MD', 'MA', 'MI', 'MN', 'MS', 'MO', 'MT', 'NE', 'NV', 'NH',
  'NJ', 'NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI',
  'SC', 'SD', 'TN', 'TX', 'UT', 'VT', 'VA', 'WA', 'WV', 'WI', 'WY'
];

interface HUDCountyData {
  fips_code: string;
  county_name: string;
  state_name: string;
  Efficiency: number;
  One_Bedroom: number;
  Two_Bedroom: number;
  Three_Bedroom: number;
  Four_Bedroom: number;
  smallarea_status?: string;
}

interface HUDStateResponse {
  data?: {
    counties?: HUDCountyData[];
  };
}

export async function downloadHudFairMarketRent(): Promise<{ success: boolean; recordCount: number; message: string }> {
  const hudToken = process.env.HUD_API_KEY || process.env.HUD_TOKEN;

  if (!hudToken) {
    return { success: false, recordCount: 0, message: 'HUD_API_KEY not configured' };
  }

  try {
    console.log('[HUD Pipeline] Starting FMR download...');

    const currentYear = new Date().getFullYear();
    const fiscalYear = currentYear;
    let totalRecords = 0;
    const errors: string[] = [];

    await db.delete(hudFairMarketRent).where(eq(hudFairMarketRent.fiscalYear, fiscalYear));

    for (const stateCode of STATE_CODES) {
      try {
        const url = `${HUD_API_BASE}/statedata/${stateCode}?year=${fiscalYear}`;

        const response = await fetch(url, {
          headers: {
            'Authorization': `Bearer ${hudToken}`,
            'Content-Type': 'application/json'
          }
        });

        if (!response.ok) {
          errors.push(`${stateCode}: HTTP ${response.status}`);
          continue;
        }

        const data: HUDStateResponse = await response.json();
        const counties = data?.data?.counties || [];

        if (counties.length === 0) {
          continue;
        }

        const records = counties.map(county => ({
          fiscalYear,
          stateCode,
          countyCode: county.fips_code,
          countyName: county.county_name,
          areaName: `${county.county_name}, ${county.state_name}`,
          efficiency: county.Efficiency || null,
          oneBedroom: county.One_Bedroom || null,
          twoBedroom: county.Two_Bedroom || null,
          threeBedroom: county.Three_Bedroom || null,
          fourBedroom: county.Four_Bedroom || null,
          smallAreaFmr: county.smallarea_status === '1',
        }));

        if (records.length > 0) {
          await db.insert(hudFairMarketRent).values(records);
          totalRecords += records.length;
        }

        await delay(100);
      } catch (error) {
        errors.push(`${stateCode}: ${error instanceof Error ? error.message : 'Unknown error'}`);
      }
    }

    await updatePipelineStatus('hud_fair_market_rent', totalRecords, errors.length === 0 ? 'success' : 'partial');

    console.log(`[HUD Pipeline] Downloaded ${totalRecords} FMR records`);
    return { 
      success: true, 
      recordCount: totalRecords, 
      message: errors.length > 0 ? `Downloaded ${totalRecords} records with ${errors.length} errors` : `Downloaded ${totalRecords} records`
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    console.error('[HUD Pipeline] Error:', errorMessage);
    await updatePipelineStatus('hud_fair_market_rent', 0, 'error', errorMessage);
    return { success: false, recordCount: 0, message: errorMessage };
  }
}

export async function getFmrFromCache(stateCode: string, countyCode?: string): Promise<{
  efficiency: number | null;
  oneBedroom: number | null;
  twoBedroom: number | null;
  threeBedroom: number | null;
  fourBedroom: number | null;
  countyName: string | null;
  fiscalYear: number;
} | null> {
  const currentYear = new Date().getFullYear();

  let query = db
    .select()
    .from(hudFairMarketRent)
    .where(
      and(
        eq(hudFairMarketRent.stateCode, stateCode.toUpperCase()),
        eq(hudFairMarketRent.fiscalYear, currentYear)
      )
    )
    .limit(1);

  const records = await query;

  if (records.length === 0) {
    return null;
  }

  const record = records[0];
  return {
    efficiency: record.efficiency,
    oneBedroom: record.oneBedroom,
    twoBedroom: record.twoBedroom,
    threeBedroom: record.threeBedroom,
    fourBedroom: record.fourBedroom,
    countyName: record.countyName,
    fiscalYear: record.fiscalYear,
  };
}

function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function updatePipelineStatus(
  dataSource: string,
  recordCount: number,
  status: 'success' | 'error' | 'pending' | 'partial',
  errorMessage?: string
): Promise<void> {
  const now = new Date();

  await db
    .insert(dataPipelineStatus)
    .values({
      dataSource,
      lastDownloadAt: now,
      lastSuccessAt: status === 'success' || status === 'partial' ? now : undefined,
      recordCount,
      status,
      errorMessage: errorMessage || null,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: dataPipelineStatus.dataSource,
      set: {
        lastDownloadAt: now,
        lastSuccessAt: status === 'success' || status === 'partial' ? now : sql`${dataPipelineStatus.lastSuccessAt}`,
        recordCount,
        status,
        errorMessage: errorMessage || null,
        updatedAt: now,
      },
    });
}

client/src/components/EnhancedSafetyScor.content:
import { Card } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Shield, TrendingUp, TrendingDown, Minus, AlertTriangle, CheckCircle, Info, MapPin, Building2, Globe, FileText } from 'lucide-react';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import type { EnrichedCrimeData, CrimeData } from '@shared/schema';
import CrimeMap from './CrimeMap';

const getGradeExplanation = (grade: string): string => {
  const gradeUpper = grade.toUpperCase().replace(/[+-]/g, '');
  switch (gradeUpper) {
    case 'A':
      return 'Excellent safety. This ZIP code has significantly lower crime rates than the national average.';
    case 'B':
      return 'Good safety. Crime rates in this area are below the national average.';
    case 'C':
      return 'Average safety. Crime rates are comparable to the national average.';
    case 'D':
      return 'Below average safety. Crime rates are higher than the national average.';
    case 'F':
      return 'Poor safety. This area has significantly elevated crime rates compared to national averages.';
    default:
      return 'Crime data is being evaluated for this area.';
  }
};

interface EnhancedSafetyScoreProps {
  enrichedData: EnrichedCrimeData | null;
  legacyData: CrimeData | null;
}

export default function EnhancedSafetyScore({ enrichedData, legacyData }: EnhancedSafetyScoreProps) {
  if (!enrichedData && !legacyData) {
    return (
      <Card className="p-6 glass-card border-gray-700/50" data-testid="card-safety-score-unavailable">
        <div className="flex items-center gap-3 mb-4">
          <div className="p-3 rounded-lg bg-gray-500/10 border border-gray-500/20">
            <Shield className="w-6 h-6 text-gray-400" />
          </div>
          <div>
            <h3 className="text-lg font-semibold text-white">Safety Analysis</h3>
            <p className="text-sm text-gray-400">Crime data unavailable</p>
          </div>
        </div>
        <p className="text-gray-400 text-sm">
          Detailed crime statistics are not available for this area. Safety estimates are based on demographic indicators.
        </p>
      </Card>
    );
  }

  const score = enrichedData?.compositeSafetyScore ?? legacyData?.safetyScore ?? 50;
  const label = enrichedData?.safetyLabel ?? 'Average';
  const gradeColor = enrichedData?.safetyColor ?? '#eab308';

  const getScoreStyles = (score: number) => {
    if (score >= 85) return { bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', text: 'text-emerald-400', glow: 'drop-shadow-[0_0_8px_rgba(52,211,153,0.5)]' };
    if (score >= 70) return { bg: 'bg-lime-500/10', border: 'border-lime-500/30', text: 'text-lime-400', glow: 'drop-shadow-[0_0_8px_rgba(132,204,22,0.5)]' };
    if (score >= 55) return { bg: 'bg-yellow-500/10', border: 'border-yellow-500/30', text: 'text-yellow-400', glow: 'drop-shadow-[0_0_8px_rgba(234,179,8,0.5)]' };
    if (score >= 40) return { bg: 'bg-orange-500/10', border: 'border-orange-500/30', text: 'text-orange-400', glow: 'drop-shadow-[0_0_8px_rgba(249,115,22,0.5)]' };
    return { bg: 'bg-red-500/10', border: 'border-red-500/30', text: 'text-red-400', glow: 'drop-shadow-[0_0_8px_rgba(239,68,68,0.5)]' };
  };

  const styles = getScoreStyles(score);
  const zipData = enrichedData?.zipLevelData;
  const stateData = enrichedData?.stateLevelData;

  const ComparisonIndicator = ({ value, label: compLabel }: { value: number; label: string }) => {
    if (Math.abs(value) < 5) {
      return (
        <div className="flex items-center gap-1 text-gray-400">
          <Minus className="w-4 h-4" />
          <span className="text-xs">{compLabel}</span>
        </div>
      );
    }
    if (value < 0) {
      return (
        <div className="flex items-center gap-1 text-emerald-400">
          <TrendingDown className="w-4 h-4" />
          <span className="text-xs">{Math.abs(Math.round(value))}% below national avg</span>
        </div>
      );
    }
    return (
      <div className="flex items-center gap-1 text-orange-400">
        <TrendingUp className="w-4 h-4" />
        <span className="text-xs">{Math.round(value)}% above national avg</span>
      </div>
    );
  };

  return (
    <Card className="p-6 glass-card card-glow-hover border-gray-700/50" data-testid="card-enhanced-safety-score">
      <div className="flex items-start gap-4 mb-6">
        <div className={`p-3 rounded-lg ${styles.bg} border ${styles.border}`}>
          <Shield className={`w-6 h-6 ${styles.text} icon-glow`} />
        </div>
        <div className="flex-1">
          <div className="flex items-center justify-between mb-1">
            <h3 className="text-sm font-medium uppercase tracking-wide text-gray-400">Safety Analysis</h3>
            <Tooltip>
              <TooltipTrigger asChild>
                <button className="p-1 rounded-full hover:bg-white/5 transition-colors" data-testid="button-tooltip-safety">
                  <Info className="w-4 h-4 text-gray-500 hover:text-cyan-400 transition-colors" />
                </button>
              </TooltipTrigger>
              <TooltipContent className="max-w-xs glass border-gray-700" side="top">
                <p className="text-sm text-gray-300">
                  Composite safety score from multiple data sources including ZIP-level crime grades, state-level FBI statistics, and national benchmarks (NIBRS).
                </p>
              </TooltipContent>
            </Tooltip>
          </div>

          <div className="flex items-baseline gap-3 mb-2">
            <span className={`text-4xl font-bold font-mono ${styles.text} ${styles.glow}`} data-testid="text-safety-score">
              {score}
            </span>
            <Badge 
              className="text-xs font-medium" 
              style={{ backgroundColor: `${gradeColor}20`, color: gradeColor, borderColor: `${gradeColor}40` }}
              data-testid="badge-safety-label"
            >
              {label}
            </Badge>
          </div>

          {enrichedData?.summary && (
            <p className="text-sm text-gray-400 mb-3" data-testid="text-safety-description">
              {enrichedData.summary.description}
            </p>
          )}

          <div className="h-2 bg-gray-800 rounded-full overflow-hidden mb-4">
            <div 
              className={`h-full transition-all duration-500 ${score >= 85 ? 'bg-gradient-to-r from-emerald-500 to-emerald-400' : score >= 70 ? 'bg-gradient-to-r from-lime-500 to-lime-400' : score >= 55 ? 'bg-gradient-to-r from-yellow-500 to-yellow-400' : score >= 40 ? 'bg-gradient-to-r from-orange-500 to-orange-400' : 'bg-gradient-to-r from-red-500 to-red-400'}`}
              style={{ width: `${score}%` }}
            />
          </div>
        </div>
      </div>

      {zipData && (
        <div className="mb-4 p-4 rounded-lg bg-gray-800/50 border border-gray-700/50" data-testid="section-zip-crime">
          <div className="flex items-center gap-2 mb-3">
            <MapPin className="w-4 h-4 text-cyan-400" />
            <span className="text-sm font-medium text-white">ZIP Code Crime Grade</span>
            <Badge className="text-xs" style={{ backgroundColor: `${zipData.gradeColor}20`, color: zipData.gradeColor }}>
              {zipData.dataYear}
            </Badge>
          </div>

          <div className="grid grid-cols-3 gap-4 mb-3">
            <div className="text-center">
              <div 
                className="text-2xl font-bold mb-1" 
                style={{ color: zipData.gradeColor }}
                data-testid="text-overall-grade"
              >
                {zipData.overallGrade}
              </div>
              <div className="text-xs text-gray-400">Overall</div>
            </div>
            <div className="text-center">
              <div className="text-lg font-semibold text-white mb-1" data-testid="text-violent-grade">
                {zipData.violentCrimeGrade}
              </div>
              <div className="text-xs text-gray-400">Violent Crime</div>
            </div>
            <div className="text-center">
              <div className="text-lg font-semibold text-white mb-1" data-testid="text-property-grade">
                {zipData.propertyCrimeGrade}
              </div>
              <div className="text-xs text-gray-400">Property Crime</div>
            </div>
          </div>

          <p className="text-xs text-gray-400 italic" data-testid="text-zip-explanation">
            {getGradeExplanation(zipData.overallGrade)} Grades range from A (safest) to F (least safe), based on reported crime incidents in this ZIP code.
          </p>
        </div>
      )}

      {zipData && enrichedData?.nearbyZips && enrichedData.nearbyZips.length > 0 && (
        <div className="mb-4">
          <CrimeMap
            mainZip={enrichedData.zipCode}
            mainGrade={zipData.overallGrade}
            mainGradeColor={zipData.gradeColor}
            nearbyZips={enrichedData.nearbyZips}
            centerLat={enrichedData.lat}
            centerLng={enrichedData.lng}
          />
        </div>
      )}

      {stateData && (
        <Accordion type="single" collapsible className="w-full">
          <AccordionItem value="state-stats" className="border-gray-700/50">
            <AccordionTrigger className="hover:no-underline py-3" data-testid="button-expand-state-stats">
              <div className="flex items-center gap-2">
                <Building2 className="w-4 h-4 text-purple-400" />
                <span className="text-sm font-medium text-white">State Crime Statistics</span>
                <Badge variant="outline" className="text-xs border-gray-600 text-gray-400">
                  {enrichedData?.stateName || ''} {stateData.dataYear}
                </Badge>
              </div>
            </AccordionTrigger>
            <AccordionContent>
              <div className="space-y-4 pt-2">
                <p className="text-xs text-gray-400 italic" data-testid="text-state-explanation">
                  These statistics are from the FBI's Uniform Crime Reporting (UCR) program for {enrichedData?.stateName || 'this state'}. 
                  Crime rates are shown per 100,000 residents and compared against national averages to help you understand how this state compares to the rest of the country.
                </p>

                <div className="grid grid-cols-2 gap-4">
                  <div className="p-3 rounded-lg bg-gray-800/50">
                    <div className="text-xs text-gray-400 mb-1">Violent Crime Rate</div>
                    <div className="text-lg font-semibold text-white" data-testid="text-violent-rate">
                      {stateData.violentCrimeRate.toFixed(0)}/100K
                    </div>
                    <ComparisonIndicator value={stateData.violentCrimeVsNational} label={stateData.violentCrimeComparison} />
                  </div>
                  <div className="p-3 rounded-lg bg-gray-800/50">
                    <div className="text-xs text-gray-400 mb-1">Property Crime Rate</div>
                    <div className="text-lg font-semibold text-white" data-testid="text-property-rate">
                      {stateData.propertyCrimeRate.toFixed(0)}/100K
                    </div>
                    <ComparisonIndicator value={stateData.propertyCrimeVsNational} label={stateData.propertyCrimeComparison} />
                  </div>
                </div>

                <div className="grid grid-cols-3 gap-2 text-center">
                  <div className="p-2 rounded bg-gray-800/30">
                    <div className="text-xs text-gray-500">Murder</div>
                    <div className="text-sm font-medium text-gray-300">{stateData.murderRate.toFixed(1)}</div>
                  </div>
                  <div className="p-2 rounded bg-gray-800/30">
                    <div className="text-xs text-gray-500">Robbery</div>
                    <div className="text-sm font-medium text-gray-300">{stateData.robberyRate.toFixed(1)}</div>
                  </div>
                  <div className="p-2 rounded bg-gray-800/30">
                    <div className="text-xs text-gray-500">Assault</div>
                    <div className="text-sm font-medium text-gray-300">{stateData.assaultRate.toFixed(1)}</div>
                  </div>
                  <div className="p-2 rounded bg-gray-800/30">
                    <div className="text-xs text-gray-500">Burglary</div>
                    <div className="text-sm font-medium text-gray-300">{stateData.burglaryRate.toFixed(1)}</div>
                  </div>
                  <div className="p-2 rounded bg-gray-800/30">
                    <div className="text-xs text-gray-500">Larceny</div>
                    <div className="text-sm font-medium text-gray-300">{stateData.larcenyRate.toFixed(1)}</div>
                  </div>
                  <div className="p-2 rounded bg-gray-800/30">
                    <div className="text-xs text-gray-500">Vehicle Theft</div>
                    <div className="text-sm font-medium text-gray-300">{stateData.motorVehicleTheftRate.toFixed(1)}</div>
                  </div>
                </div>
              </div>
            </AccordionContent>
          </AccordionItem>
        </Accordion>
      )}

      {enrichedData?.summary.keyInsights && enrichedData.summary.keyInsights.length > 0 && (
        <div className="mt-4 pt-4 border-t border-gray-700/50">
          <div className="flex flex-wrap gap-2">
            {enrichedData.summary.keyInsights.map((insight, index) => (
              <div 
                key={index}
                className="flex items-center gap-1.5 px-2 py-1 rounded-full bg-gray-800/50 text-xs text-gray-300"
                data-testid={`badge-insight-${index}`}
              >
                {insight.toLowerCase().includes('low') || insight.toLowerCase().includes('below') ? (
                  <CheckCircle className="w-3 h-3 text-emerald-400" />
                ) : insight.toLowerCase().includes('high') || insight.toLowerCase().includes('above') || insight.toLowerCase().includes('elevated') ? (
                  <AlertTriangle className="w-3 h-3 text-orange-400" />
                ) : (
                  <Info className="w-3 h-3 text-gray-400" />
                )}
                {insight}
              </div>
            ))}
          </div>
        </div>
      )}

      <Accordion type="single" collapsible className="w-full mt-4">
        <AccordionItem value="methodology" className="border-gray-700/50">
          <AccordionTrigger className="hover:no-underline py-3" data-testid="button-expand-methodology">
            <div className="flex items-center gap-2">
              <FileText className="w-4 h-4 text-gray-400" />
              <span className="text-sm font-medium text-gray-300">How Your Score Was Calculated</span>
            </div>
          </AccordionTrigger>
          <AccordionContent>
            <div className="space-y-3 pt-2 text-xs text-gray-400">
              {zipData ? (
                <div className="flex items-start gap-2 p-2 rounded bg-cyan-500/5 border border-cyan-500/20">
                  <MapPin className="w-4 h-4 text-cyan-400 mt-0.5 shrink-0" />
                  <div>
                    <span className="text-cyan-300 font-medium">ZIP-Level Data (60% of score): </span>
                    Your property's ZIP code received a grade of <span className="font-semibold text-white">{zipData.overallGrade}</span>. 
                    This hyper-local data is the most relevant to your specific address and carries the most weight in your safety score.
                  </div>
                </div>
              ) : (
                <div className="flex items-start gap-2 p-2 rounded bg-gray-500/5 border border-gray-500/20">
                  <MapPin className="w-4 h-4 text-gray-500 mt-0.5 shrink-0" />
                  <div>
                    <span className="text-gray-300 font-medium">ZIP-Level Data: </span>
                    Not available for this ZIP code. Your score relies on state and national data instead, which provides broader regional context.
                  </div>
                </div>
              )}

              {stateData ? (
                <div className="flex items-start gap-2 p-2 rounded bg-purple-500/5 border border-purple-500/20">
                  <Building2 className="w-4 h-4 text-purple-400 mt-0.5 shrink-0" />
                  <div>
                    <span className="text-purple-300 font-medium">State Statistics ({zipData ? '40%' : '100%'} of score): </span>
                    {enrichedData?.stateName || 'This state'}'s crime rates are {stateData.violentCrimeVsNational > 5 ? 'above' : stateData.violentCrimeVsNational < -5 ? 'below' : 'near'} the national average. 
                    FBI data from {stateData.dataYear} provides official crime statistics{zipData ? '' : ' and serves as the primary source for your safety score since ZIP-level data is not available'}.
                  </div>
                </div>
              ) : (
                <div className="flex items-start gap-2 p-2 rounded bg-gray-500/5 border border-gray-500/20">
                  <Building2 className="w-4 h-4 text-gray-500 mt-0.5 shrink-0" />
                  <div>
                    <span className="text-gray-300 font-medium">State Statistics: </span>
                    State-level FBI crime data is not available. Your score uses national benchmarks as a baseline.
                  </div>
                </div>
              )}

              <div className="flex items-start gap-2 p-2 rounded bg-blue-500/5 border border-blue-500/20">
                <Globe className="w-4 h-4 text-blue-400 mt-0.5 shrink-0" />
                <div>
                  <span className="text-blue-300 font-medium">National Benchmarks: </span>
                  All scores are compared against FBI's National Incident-Based Reporting System (NIBRS) data to give you context on how this area compares to the national average.
                </div>
              </div>

              <p className="text-gray-500 mt-2 pt-2 border-t border-gray-700/30">
                Your final safety score of <span className="text-white font-semibold">{score}/100</span> reflects a weighted combination of the available data sources, 
                with more local data given higher priority when available. This score is for informational purposes only and should be one of many factors in your decision.
              </p>
            </div>
          </AccordionContent>
        </AccordionItem>
      </Accordion>

      <div className="mt-3 pt-3 border-t border-gray-700/30">
        <div className="flex flex-wrap items-center gap-2 text-xs text-gray-500">
          <span>Data sources used:</span>
          {enrichedData?.dataSources.zipCode !== 'unavailable' && (
            <Badge variant="outline" className="text-xs border-cyan-700/50 text-cyan-500">ZIP Crime Data</Badge>
          )}
          {enrichedData?.dataSources.state !== 'unavailable' && (
            <Badge variant="outline" className="text-xs border-purple-700/50 text-purple-500">FBI UCR</Badge>
          )}
          <Badge variant="outline" className="text-xs border-blue-700/50 text-blue-500">NIBRS</Badge>
        </div>
      </div>
    </Card>
  );
}

server/services/dataPipeline/zillowDownl.content:
import { db } from '../../db';
import { zillowHomeValueForecast, zillowRentForecast, zillowMarketMetrics, dataPipelineStatus } from '@shared/schema';
import { eq, and, sql } from 'drizzle-orm';
import { parse } from 'csv-parse/sync';

const ZILLOW_CSV_URLS = {
  homeValueForecast: 'https://files.zillowstatic.com/research/public_csvs/zhvf_growth/Zip_zhvf_growth_uc_sfrcondo_tier_0.33_0.67_sm_sa_month.csv',
  homeValueForecastMetro: 'https://files.zillowstatic.com/research/public_csvs/zhvf_growth/Metro_zhvf_growth_uc_sfrcondo_tier_0.33_0.67_sm_sa_month.csv',
  rentForecastSFR: 'https://files.zillowstatic.com/research/public_csvs/zorf_growth/National_zorf_growth_uc_sfr_sm_month.csv',
  daysToPending: 'https://files.zillowstatic.com/research/public_csvs/days_to_pending/Metro_days_to_pending_uc_sfrcondo_sm_month.csv',
  saleToListRatio: 'https://files.zillowstatic.com/research/public_csvs/sale_to_list/Metro_mean_sale_to_list_uc_sfrcondo_sm_month.csv',
  inventory: 'https://files.zillowstatic.com/research/public_csvs/invt_fs/Metro_invt_fs_uc_sfrcondo_sm_month.csv',
  medianListPrice: 'https://files.zillowstatic.com/research/public_csvs/mlp/Metro_mlp_uc_sfrcondo_sm_month.csv',
  percentSoldAbove: 'https://files.zillowstatic.com/research/public_csvs/pct_sold_above_list/Metro_pct_sold_above_list_uc_sfrcondo_sm_month.csv',
  percentSoldBelow: 'https://files.zillowstatic.com/research/public_csvs/pct_sold_below_list/Metro_pct_sold_below_list_uc_sfrcondo_sm_month.csv',
};

async function fetchCSV(url: string): Promise<string> {
  console.log(`[Zillow] Fetching CSV from: ${url}`);
  const response = await fetch(url, {
    headers: {
      'User-Agent': 'ScoreCasa/1.0 (Real Estate Analysis Platform)',
    },
  });

  if (!response.ok) {
    throw new Error(`Failed to fetch CSV: ${response.status} ${response.statusText}`);
  }

  return response.text();
}

function parseCSV(csvData: string): any[] {
  try {
    return parse(csvData, {
      columns: true,
      skip_empty_lines: true,
      relax_column_count: true,
    });
  } catch (error) {
    console.error('[Zillow] Error parsing CSV:', error);
    return [];
  }
}

function extractStateFromRegion(regionName: string): string | null {
  if (!regionName) return null;
  const parts = regionName.split(',');
  if (parts.length >= 2) {
    const stateAbbr = parts[parts.length - 1].trim().substring(0, 2).toUpperCase();
    if (/^[A-Z]{2}$/.test(stateAbbr)) {
      return stateAbbr;
    }
  }
  return null;
}

function getMostRecentDateColumn(record: any): { date: string; value: number } | null {
  const dateColumns = Object.keys(record).filter(key => /^\d{4}-\d{2}-\d{2}$/.test(key));
  if (dateColumns.length === 0) return null;

  dateColumns.sort((a, b) => new Date(b).getTime() - new Date(a).getTime());
  const mostRecentDate = dateColumns[0];
  const value = parseFloat(record[mostRecentDate]);

  if (isNaN(value)) return null;
  return { date: mostRecentDate, value };
}

export async function downloadZillowHomeValueForecast(): Promise<{ success: boolean; recordCount: number; error?: string }> {
  try {
    console.log('[Zillow] Starting home value forecast download...');

    const [zipCsv, metroCsv] = await Promise.all([
      fetchCSV(ZILLOW_CSV_URLS.homeValueForecast),
      fetchCSV(ZILLOW_CSV_URLS.homeValueForecastMetro),
    ]);

    const zipRecords = parseCSV(zipCsv);
    const metroRecords = parseCSV(metroCsv);

    console.log(`[Zillow] Parsed ${zipRecords.length} ZIP forecasts, ${metroRecords.length} Metro forecasts`);

    await db.delete(zillowHomeValueForecast).where(sql`1=1`);

    let insertedCount = 0;
    const batchSize = 500;

    for (let i = 0; i < zipRecords.length; i += batchSize) {
      const batch = zipRecords.slice(i, i + batchSize);
      const insertData = batch
        .map((record: any) => {
          const regionId = record.RegionID || record.RegionName;
          const regionName = record.RegionName || '';
          const stateCode = extractStateFromRegion(regionName) || record.StateName?.substring(0, 2);

          const forecastMonth = parseFloat(record['1 Month'] || record['MoM%'] || '0');
          const forecastQuarter = parseFloat(record['3 Month'] || record['QoQ%'] || '0');
          const forecastYear = parseFloat(record['1 Year'] || record['YoY%'] || '0');

          if (isNaN(forecastYear)) return null;

          return {
            regionId: String(regionId),
            regionName,
            regionType: 'zip' as const,
            stateCode: stateCode || null,
            baseDate: new Date().toISOString().split('T')[0],
            currentValue: parseFloat(record.BaseValue) || null,
            forecastMonthChange: forecastMonth || null,
            forecastQuarterChange: forecastQuarter || null,
            forecastYearChange: forecastYear || null,
          };
        })
        .filter((r): r is NonNullable<typeof r> => r !== null);

      if (insertData.length > 0) {
        await db.insert(zillowHomeValueForecast).values(insertData);
        insertedCount += insertData.length;
      }
    }

    for (let i = 0; i < metroRecords.length; i += batchSize) {
      const batch = metroRecords.slice(i, i + batchSize);
      const insertData = batch
        .map((record: any) => {
          const regionId = record.RegionID || record.RegionName;
          const regionName = record.RegionName || '';
          const stateCode = extractStateFromRegion(regionName);

          const forecastMonth = parseFloat(record['1 Month'] || record['MoM%'] || '0');
          const forecastQuarter = parseFloat(record['3 Month'] || record['QoQ%'] || '0');
          const forecastYear = parseFloat(record['1 Year'] || record['YoY%'] || '0');

          if (isNaN(forecastYear)) return null;

          return {
            regionId: String(regionId),
            regionName,
            regionType: 'metro' as const,
            stateCode: stateCode || null,
            baseDate: new Date().toISOString().split('T')[0],
            currentValue: parseFloat(record.BaseValue) || null,
            forecastMonthChange: forecastMonth || null,
            forecastQuarterChange: forecastQuarter || null,
            forecastYearChange: forecastYear || null,
          };
        })
        .filter((r): r is NonNullable<typeof r> => r !== null);

      if (insertData.length > 0) {
        await db.insert(zillowHomeValueForecast).values(insertData);
        insertedCount += insertData.length;
      }
    }

    await updatePipelineStatus('zillow_home_value_forecast', insertedCount, 'success');
    console.log(`[Zillow] Successfully inserted ${insertedCount} home value forecast records`);

    return { success: true, recordCount: insertedCount };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Zillow] Home value forecast download failed:', errorMsg);
    await updatePipelineStatus('zillow_home_value_forecast', 0, 'error', errorMsg);
    return { success: false, recordCount: 0, error: errorMsg };
  }
}

export async function downloadZillowMarketMetrics(): Promise<{ success: boolean; recordCount: number; error?: string }> {
  try {
    console.log('[Zillow] Starting market metrics download...');

    const [daysToPendingCsv, saleToListCsv, inventoryCsv, listPriceCsv, soldAboveCsv, soldBelowCsv] = await Promise.all([
      fetchCSV(ZILLOW_CSV_URLS.daysToPending),
      fetchCSV(ZILLOW_CSV_URLS.saleToListRatio),
      fetchCSV(ZILLOW_CSV_URLS.inventory),
      fetchCSV(ZILLOW_CSV_URLS.medianListPrice),
      fetchCSV(ZILLOW_CSV_URLS.percentSoldAbove),
      fetchCSV(ZILLOW_CSV_URLS.percentSoldBelow),
    ]);

    const daysToPendingRecords = parseCSV(daysToPendingCsv);
    const saleToListRecords = parseCSV(saleToListCsv);
    const inventoryRecords = parseCSV(inventoryCsv);
    const listPriceRecords = parseCSV(listPriceCsv);
    const soldAboveRecords = parseCSV(soldAboveCsv);
    const soldBelowRecords = parseCSV(soldBelowCsv);

    console.log(`[Zillow] Parsed market metrics: ${daysToPendingRecords.length} regions`);

    await db.delete(zillowMarketMetrics).where(sql`1=1`);

    const metricsMap = new Map<string, any>();

    const processRecords = (records: any[], metricName: string) => {
      for (const record of records) {
        const regionId = record.RegionID || record.RegionName;
        if (!regionId) continue;

        const recent = getMostRecentDateColumn(record);
        if (!recent) continue;

        if (!metricsMap.has(regionId)) {
          metricsMap.set(regionId, {
            regionId: String(regionId),
            regionName: record.RegionName || '',
            regionType: 'metro',
            stateCode: extractStateFromRegion(record.RegionName || ''),
            metricDate: recent.date,
          });
        }

        const existing = metricsMap.get(regionId);
        existing[metricName] = recent.value;
      }
    };

    processRecords(daysToPendingRecords, 'daysToPending');
    processRecords(saleToListRecords, 'saleToListRatio');
    processRecords(inventoryRecords, 'inventoryForSale');
    processRecords(listPriceRecords, 'medianListPrice');
    processRecords(soldAboveRecords, 'percentSoldAboveList');
    processRecords(soldBelowRecords, 'percentSoldBelowList');

    const allMetrics = Array.from(metricsMap.values());
    let insertedCount = 0;
    const batchSize = 500;

    for (let i = 0; i < allMetrics.length; i += batchSize) {
      const batch = allMetrics.slice(i, i + batchSize);
      const insertData = batch.map(m => ({
        regionId: m.regionId,
        regionName: m.regionName,
        regionType: m.regionType,
        stateCode: m.stateCode || null,
        metricDate: m.metricDate,
        daysToPending: m.daysToPending ?? null,
        saleToListRatio: m.saleToListRatio ?? null,
        inventoryForSale: m.inventoryForSale ? Math.round(m.inventoryForSale) : null,
        newListings: null,
        medianListPrice: m.medianListPrice ?? null,
        percentSoldAboveList: m.percentSoldAboveList ?? null,
        percentSoldBelowList: m.percentSoldBelowList ?? null,
      }));

      await db.insert(zillowMarketMetrics).values(insertData);
      insertedCount += insertData.length;
    }

    await updatePipelineStatus('zillow_market_metrics', insertedCount, 'success');
    console.log(`[Zillow] Successfully inserted ${insertedCount} market metrics records`);

    return { success: true, recordCount: insertedCount };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Zillow] Market metrics download failed:', errorMsg);
    await updatePipelineStatus('zillow_market_metrics', 0, 'error', errorMsg);
    return { success: false, recordCount: 0, error: errorMsg };
  }
}

export async function downloadZillowRentForecast(): Promise<{ success: boolean; recordCount: number; error?: string }> {
  try {
    console.log('[Zillow] Starting rent forecast download...');

    const csv = await fetchCSV(ZILLOW_CSV_URLS.rentForecastSFR);
    const records = parseCSV(csv);

    console.log(`[Zillow] Parsed ${records.length} rent forecast records`);

    await db.delete(zillowRentForecast).where(sql`1=1`);

    const insertData = records
      .map((record: any) => {
        const forecastMonth = parseFloat(record['1 Month'] || record['MoM%'] || '0');
        const forecastQuarter = parseFloat(record['3 Month'] || record['QoQ%'] || '0');
        const forecastYear = parseFloat(record['1 Year'] || record['YoY%'] || '0');

        if (isNaN(forecastYear)) return null;

        return {
          regionId: 'US',
          regionName: 'United States',
          regionType: 'country' as const,
          stateCode: null,
          baseDate: new Date().toISOString().split('T')[0],
          currentRent: parseFloat(record.BaseValue) || null,
          forecastMonthChange: forecastMonth || null,
          forecastQuarterChange: forecastQuarter || null,
          forecastYearChange: forecastYear || null,
        };
      })
      .filter((r): r is NonNullable<typeof r> => r !== null);

    if (insertData.length > 0) {
      await db.insert(zillowRentForecast).values(insertData);
    }

    await updatePipelineStatus('zillow_rent_forecast', insertData.length, 'success');
    console.log(`[Zillow] Successfully inserted ${insertData.length} rent forecast records`);

    return { success: true, recordCount: insertData.length };
  } catch (error) {
    const errorMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Zillow] Rent forecast download failed:', errorMsg);
    await updatePipelineStatus('zillow_rent_forecast', 0, 'error', errorMsg);
    return { success: false, recordCount: 0, error: errorMsg };
  }
}

export async function downloadAllZillowData(): Promise<{
  homeValueForecast: { success: boolean; recordCount: number; error?: string };
  rentForecast: { success: boolean; recordCount: number; error?: string };
  marketMetrics: { success: boolean; recordCount: number; error?: string };
}> {
  console.log('[Zillow] Starting full data download...');

  const [homeValueForecast, rentForecast, marketMetrics] = await Promise.all([
    downloadZillowHomeValueForecast(),
    downloadZillowRentForecast(),
    downloadZillowMarketMetrics(),
  ]);

  return { homeValueForecast, rentForecast, marketMetrics };
}

async function updatePipelineStatus(
  dataSource: string,
  recordCount: number,
  status: 'success' | 'error',
  errorMessage?: string
): Promise<void> {
  try {
    const existing = await db
      .select()
      .from(dataPipelineStatus)
      .where(eq(dataPipelineStatus.dataSource, dataSource))
      .limit(1);

    const now = new Date();
    const nextScheduled = new Date(now);
    nextScheduled.setMonth(nextScheduled.getMonth() + 1);
    nextScheduled.setDate(16);

    if (existing.length > 0) {
      await db
        .update(dataPipelineStatus)
        .set({
          lastDownloadAt: now,
          lastSuccessAt: status === 'success' ? now : existing[0].lastSuccessAt,
          recordCount: status === 'success' ? recordCount : existing[0].recordCount,
          status,
          errorMessage: errorMessage || null,
          nextScheduledAt: nextScheduled,
          updatedAt: now,
        })
        .where(eq(dataPipelineStatus.dataSource, dataSource));
    } else {
      await db.insert(dataPipelineStatus).values({
        dataSource,
        lastDownloadAt: now,
        lastSuccessAt: status === 'success' ? now : null,
        recordCount: status === 'success' ? recordCount : 0,
        status,
        errorMessage: errorMessage || null,
        nextScheduledAt: nextScheduled,
      });
    }
  } catch (error) {
    console.error(`[Zillow] Failed to update pipeline status for ${dataSource}:`, error);
  }
}

server/services/dataPipeline/censusPermi.content:
import { db } from '../../db';
import { censusBuildingPermits, dataPipelineStatus } from '@shared/schema';
import { eq, and, desc, sql } from 'drizzle-orm';

const CENSUS_PERMITS_API = 'https://api.census.gov/data/timeseries/bps';

const STATE_FIPS: Record<string, string> = {
  'AL': '01', 'AK': '02', 'AZ': '04', 'AR': '05', 'CA': '06',
  'CO': '08', 'CT': '09', 'DE': '10', 'DC': '11', 'FL': '12',
  'GA': '13', 'HI': '15', 'ID': '16', 'IL': '17', 'IN': '18',
  'IA': '19', 'KS': '20', 'KY': '21', 'LA': '22', 'ME': '23',
  'MD': '24', 'MA': '25', 'MI': '26', 'MN': '27', 'MS': '28',
  'MO': '29', 'MT': '30', 'NE': '31', 'NV': '32', 'NH': '33',
  'NJ': '34', 'NM': '35', 'NY': '36', 'NC': '37', 'ND': '38',
  'OH': '39', 'OK': '40', 'OR': '41', 'PA': '42', 'RI': '44',
  'SC': '45', 'SD': '46', 'TN': '47', 'TX': '48', 'UT': '49',
  'VT': '50', 'VA': '51', 'WA': '53', 'WV': '54', 'WI': '55', 'WY': '56'
};

const FIPS_TO_STATE: Record<string, string> = Object.fromEntries(
  Object.entries(STATE_FIPS).map(([state, fips]) => [fips, state])
);

export async function downloadCensusBuildingPermits(): Promise<{ success: boolean; recordCount: number; message: string }> {
  const censusKey = process.env.CENSUS_API_KEY;

  try {
    console.log('[Census Permits Pipeline] Starting building permits download...');

    const currentYear = new Date().getFullYear();
    const years = [currentYear, currentYear - 1, currentYear - 2];
    let totalRecords = 0;
    const errors: string[] = [];

    for (const year of years) {
      try {
        const url = `${CENSUS_PERMITS_API}/metro?get=NAME,BLDGS,UNITS&for=state:*&time=${year}${censusKey ? `&key=${censusKey}` : ''}`;

        console.log(`[Census Permits Pipeline] Fetching year ${year}...`);

        const response = await fetch(url);

        if (!response.ok) {
          errors.push(`Year ${year}: HTTP ${response.status}`);
          continue;
        }

        const data = await response.json();

        if (!data || data.length < 2) {
          errors.push(`Year ${year}: No data returned`);
          continue;
        }

        const headers = data[0] as string[];
        const rows = data.slice(1) as string[][];

        const nameIdx = headers.indexOf('NAME');
        const bldgsIdx = headers.indexOf('BLDGS');
        const unitsIdx = headers.indexOf('UNITS');
        const stateIdx = headers.indexOf('state');

        const records = rows.map(row => {
          const stateFips = row[stateIdx];
          const stateCode = FIPS_TO_STATE[stateFips] || 'XX';

          return {
            stateCode,
            stateFips,
            areaName: row[nameIdx] || null,
            year,
            totalUnits: parseInt(row[unitsIdx]) || null,
            totalBuildings: parseInt(row[bldgsIdx]) || null,
            singleFamilyUnits: Math.round((parseInt(row[unitsIdx]) || 0) * 0.65),
            multiFamilyUnits: Math.round((parseInt(row[unitsIdx]) || 0) * 0.35),
          };
        }).filter(r => r.stateCode !== 'XX');

        for (const record of records) {
          await db
            .insert(censusBuildingPermits)
            .values(record)
            .onConflictDoNothing();
          totalRecords++;
        }

        await delay(300);
      } catch (error) {
        errors.push(`Year ${year}: ${error instanceof Error ? error.message : 'Unknown error'}`);
      }
    }

    await updatePipelineStatus('census_building_permits', totalRecords, errors.length === 0 ? 'success' : 'partial');

    console.log(`[Census Permits Pipeline] Downloaded ${totalRecords} permit records`);
    return { 
      success: true, 
      recordCount: totalRecords, 
      message: errors.length > 0 ? `Downloaded ${totalRecords} records with ${errors.length} errors` : `Downloaded ${totalRecords} records`
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Census Permits Pipeline] Error:', errorMessage);
    await updatePipelineStatus('census_building_permits', 0, 'error', errorMessage);
    return { success: false, recordCount: 0, message: errorMessage };
  }
}

export async function getPermitsFromCache(stateCode: string): Promise<{
  year: number;
  totalUnits: number | null;
  totalBuildings: number | null;
  singleFamilyUnits: number | null;
  multiFamilyUnits: number | null;
} | null> {
  const records = await db
    .select()
    .from(censusBuildingPermits)
    .where(eq(censusBuildingPermits.stateCode, stateCode.toUpperCase()))
    .orderBy(desc(censusBuildingPermits.year))
    .limit(1);

  if (records.length === 0) {
    return null;
  }

  const record = records[0];
  return {
    year: record.year,
    totalUnits: record.totalUnits,
    totalBuildings: record.totalBuildings,
    singleFamilyUnits: record.singleFamilyUnits,
    multiFamilyUnits: record.multiFamilyUnits,
  };
}

export async function getPermitsTrend(stateCode: string): Promise<{
  year: number;
  totalUnits: number | null;
}[]> {
  const records = await db
    .select({
      year: censusBuildingPermits.year,
      totalUnits: censusBuildingPermits.totalUnits,
    })
    .from(censusBuildingPermits)
    .where(eq(censusBuildingPermits.stateCode, stateCode.toUpperCase()))
    .orderBy(desc(censusBuildingPermits.year))
    .limit(5);

  return records;
}

function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function updatePipelineStatus(
  dataSource: string,
  recordCount: number,
  status: 'success' | 'error' | 'pending' | 'partial',
  errorMessage?: string
): Promise<void> {
  const now = new Date();

  await db
    .insert(dataPipelineStatus)
    .values({
      dataSource,
      lastDownloadAt: now,
      lastSuccessAt: status === 'success' || status === 'partial' ? now : undefined,
      recordCount,
      status,
      errorMessage: errorMessage || null,
      updatedAt: now,
    })
    .onConflictDoUpdate({
      target: dataPipelineStatus.dataSource,
      set: {
        lastDownloadAt: now,
        lastSuccessAt: status === 'success' || status === 'partial' ? now : sql`${dataPipelineStatus.lastSuccessAt}`,
        recordCount,
        status,
        errorMessage: errorMessage || null,
        updatedAt: now,
      },
    });
}

