                  <p className="text-xs text-gray-400">
                    Avg Price/SqFt from {validComps.length} comp{validComps.length > 1 ? 's' : ''}: <span className="text-cyan-400 font-medium">${avgPricePerSqFt.toFixed(2)}/sqft</span>
