                {formatCurrency(totalInvestment)}
              </span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-white font-medium">ARV (Sale Price)</span>
              <span className="text-cyan-400 font-bold">{formatCurrency(arv)}</span>
